file.content:
-- Migration 001: LLM cost ledger (Issue #2) -- Tracks every LLM call for precise cost accounting and relay.fast balance reconciliation.
create table llm_calls ( id bigserial primary key, task_id uuid not null references tasks(id) on delete cascade, worker_id text not null, lease_epoch bigint not null,
-- Request metadata model text not null, provider text not null default 'relay.fast',
-- Token usage (input/output/cached) prompt_tokens bigint not null check (prompt_tokens >= 0), completion_tokens bigint not null check (completion_tokens >= 0), cached_tokens bigint not null default 0 check (cached_tokens >= 0),
-- Cost tracking (USD, 6 decimal places for micro-transactions) prompt_cost_usd numeric(12,6) not null check (prompt_cost_usd >= 0), completion_cost_usd numeric(12,6) not null check (completion_cost_usd >= 0), total_cost_usd numeric(12,6) not null check (total_cost_usd >= 0),
-- Timing started_at timestamptz not null, completed_at timestamptz not null, duration_ms bigint not null check (duration_ms >= 0),
-- Response metadata success boolean not null, error_code text, error_message text,
-- Audit trail created_at timestamptz not null default now(),
check (completed_at >= started_at) );
create index llm_calls_task_idx on llm_calls (task_id); create index llm_calls_worker_idx on llm_calls (worker_id); create index llm_calls_created_idx on llm_calls (created_at desc); create index llm_calls_cost_idx on llm_calls (total_cost_usd) where total_cost_usd > 0;
-- View: Daily cost summary create view llm_costs_daily as select date_trunc('day', created_at at time zone 'UTC') as day, model, count(*) as calls, sum(prompt_tokens + completion_tokens) as total_tokens, sum(prompt_tokens) as prompt_tokens, sum(completion_tokens) as completion_tokens, sum(cached_tokens) as cached_tokens, sum(total_cost_usd) as total_cost_usd, count(*) filter (where not success) as errors from llm_calls group by 1, 2 order by 1 desc, 2;
-- View: Per-task cost summary create view llm_costs_by_task as select t.id as task_id, t.root_id, t.state, count(l.*) as llm_calls, sum(l.prompt_tokens + l.completion_tokens) as total_tokens, sum(l.total_cost_usd) as total_cost_usd, t.spent_tokens, t.budget_cap from tasks t left join llm_calls l on l.task_id = t.id group by t.id order by total_cost_usd desc nulls last;
comment on table llm_calls is 'Issue #2: LLM cost ledger for precise accounting and relay.fast reconciliation'; comment on column llm_calls.cached_tokens is 'Prompt cache hits (relay.fast Claude models)'; comment on column llm_calls.total_cost_usd is 'prompt_cost_usd + completion_cost_usd'; comment on view llm_costs_daily is 'Daily cost breakdown by model'; comment on view llm_costs_by_task is 'Per-task cost summary with budget tracking';

-- Migration 002: GRANT для llm_calls worker-ролям (Issue #9, #11)
--
-- Проблема: migration 001 создала таблицу llm_calls и view, но выдала права
-- только роли-владельцу (swarm). Workers подключаются как swarm_worker_w1/w2,
-- поэтому INSERT в llm_calls падал с "permission denied for table llm_calls",
-- а ошибка проглатывалась в worker.rs (warn, не fail).
-- Итог: таблица всегда была пустой, расходы LLM не учитывались.
--
-- Фикс: выдать INSERT/SELECT на llm_calls и SELECT на view всем worker-ролям.
-- GRANT идемпотентен, применять безопасно повторно.

-- Таблица llm_calls: workers пишут метрики, читать им тоже нужно для отладки.
grant insert, select on llm_calls to swarm_worker_w1;
grant insert, select on llm_calls to swarm_worker_w2;
grant insert, select on llm_calls to swarm_worker_gpu_1;
grant insert, select on llm_calls to swarm_worker_w_1;

-- Sequence для bigserial id — без него INSERT падает на nextval().
grant usage, select on sequence llm_calls_id_seq to swarm_worker_w1;
grant usage, select on sequence llm_calls_id_seq to swarm_worker_w2;
grant usage, select on sequence llm_calls_id_seq to swarm_worker_gpu_1;
grant usage, select on sequence llm_calls_id_seq to swarm_worker_w_1;

-- View для сводок — читать нужно оператору, planner и reviewer.
grant select on llm_costs_daily to swarm_operator;
grant select on llm_costs_daily to swarm_planner;
grant select on llm_costs_daily to swarm_reviewer;
grant select on llm_costs_daily to swarm_watchdog;

grant select on llm_costs_by_task to swarm_operator;
grant select on llm_costs_by_task to swarm_planner;
grant select on llm_costs_by_task to swarm_reviewer;
grant select on llm_costs_by_task to swarm_watchdog;

-- Migration 003: владелец объектов llm_* — swarm_owner, а не суперпользователь. -- -- Проблема (найдена аудитом проверки, 2026-10-13): migration 001 создавала -- llm_calls/view/sequence от имени POSTGRES_USER (в проде — суперпользователь -- `swarm`). Базовые таблицы переводит на `swarm_owner` файл roles.sql, но он -- выполняется ДО миграций, поэтому созданные позже объекты llm_* остались -- принадлежать суперпользователю. -- -- Инвариант каталога (step2/test_roles.py::test_catalog_invariants): ни одна -- таблица в public не должна принадлежать суперпользователю — иначе владелец -- может отключить защитные триггеры и в обход SECURITY DEFINER-функций менять -- состояние. Дефект был невидим, пока acceptance-harness не применял миграции -- к тест-БД; после исправления harness тест честно покраснел. -- -- Идемпотентно: повторный запуск безопасен (ALTER OWNER с текущим владельцем).
alter table if exists public.llm_calls owner to swarm_owner; alter sequence if exists public.llm_calls_id_seq owner to swarm_owner; alter view if exists public.llm_costs_daily owner to swarm_owner; alter view if exists public.llm_costs_by_task owner to swarm_owner;
-- Индексы принадлежат таблице автоматически, но зафиксируем явно на случай, -- если таблица пересоздавалась отдельно от индексов. do $$ declare idx record; begin for idx in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'i' and c.relname like 'llm_calls%' loop execute format('alter index if exists public.%I owner to swarm_owner', idx.relname); end loop; end $$;
-- Права worker-ролям выданы в 002 и от смены владельца не зависят.

-- Migration 004: стоимость в numeric(18,10) вместо numeric(12,6) (Issue #14). -- -- Проблема: numeric(12,6) хранит 6 знаков после запятой. Расход на дешёвых -- моделях меньше $0.000001 за вызов, поэтому округлялся в 0.000000 — cost ledger -- (Issue #2) и hard budget guard (Issue #3) теряли такие вызовы без следа. -- Накопленно: 10k вызовов × $0.0000004 = $0.004, которые не видно в отчётах. -- -- Фикс: 10 знаков после запятой (точность до 1e-10). Максимум numeric(18,10) = -- 99 999 999.9999999999 USD — с запасом на любой суммарный бюджет. -- -- ВАЖНО: ALTER COLUMN ... TYPE нельзя выполнить, пока от колонки зависит view -- (`rule _RETURN on view ... depends on column`). Поэтому сначала снимаем оба -- view, меняем типы, затем пересоздаём view с теми же определениями. -- -- Идемпотентно: `drop view if exists` + пересоздание; повторный ALTER TYPE на -- уже расширенную колонку — no-op (Postgres перепишет тип без потери данных).
drop view if exists public.llm_costs_daily; drop view if exists public.llm_costs_by_task;
alter table if exists public.llm_calls alter column prompt_cost_usd type numeric(18,10), alter column completion_cost_usd type numeric(18,10), alter column total_cost_usd type numeric(18,10);
-- View: Daily cost summary (определение из 001, без изменений). create view public.llm_costs_daily as select date_trunc('day', created_at at time zone 'UTC') as day, model, count(*) as calls, sum(prompt_tokens + completion_tokens) as total_tokens, sum(prompt_tokens) as prompt_tokens, sum(completion_tokens) as completion_tokens, sum(cached_tokens) as cached_tokens, sum(total_cost_usd) as total_cost_usd, count(*) filter (where not success) as errors from public.llm_calls group by 1, 2 order by 1 desc, 2;
-- View: Per-task cost summary (определение из 001, без изменений). create view public.llm_costs_by_task as select t.id as task_id, t.root_id, t.state, count(l.*) as llm_calls, sum(l.prompt_tokens + l.completion_tokens) as total_tokens, sum(l.total_cost_usd) as total_cost_usd, t.spent_tokens, t.budget_cap from public.tasks t left join public.llm_calls l on l.task_id = t.id group by t.id order by total_cost_usd desc nulls last;
-- Пересозданные view снова принадлежат swarm_owner (см. 003) и требуют грантов -- из 002: `create or replace view` их не теряет, но `drop`+`create` — теряет. alter view public.llm_costs_daily owner to swarm_owner; alter view public.llm_costs_by_task owner to swarm_owner;
grant select on public.llm_costs_daily to swarm_operator, swarm_planner, swarm_reviewer, swarm_watchdog; grant select on public.llm_costs_by_task to swarm_operator, swarm_planner, swarm_reviewer, swarm_watchdog;

-- Migration 005: состояние budget_exhausted доезжает до существующих БД
-- (Issue #20).
--
-- Проблема: Issue #3 добавил состояния `budget_exhausted`/`failed` в
-- `schema/schema_v0.sql` (inline CHECK на tasks.state) и в тела функций.
-- Но `schema_v0.sql` применяется ТОЛЬКО при первой инициализации данных
-- (docker-entrypoint-initdb.d); на уже существующей БД (named volume) он не
-- перезапускается. Поэтому в проде:
--   * constraint остался старым — без `budget_exhausted`/`failed`;
--   * `complete_task` после #20 начал возвращать `budget_exhausted` → UPDATE
--     нарушал CHECK → задача падала с «database error» и зависала в `leased`.
--
-- Симптом (лог воркера): `executing complete_task(...)` → `task failed:
-- database error`, событие `completed` не пишется.
--
-- Фикс (идемпотентно):
--   1. Расширить CHECK на tasks.state до канонического набора состояний;
--   2. Переопределить `complete_task` с семантикой #3/#20 (`budget_exhausted`);
--   3. Сохранить владельца (swarm_owner) и security definer.
--
-- На свежей БД (schema_v0.sql + roles_2b.sql уже актуальны) миграция — no-op.

-- 1. Constraint на state.
--    Inline CHECK из schema_v0.sql Postgres именует `<table>_<column>_check`
--    (tasks_state_check). Пересоздаём его с полным набором состояний.
alter table public.tasks drop constraint if exists tasks_state_check;
alter table public.tasks
  add constraint tasks_state_check
  check (state in ('pending','ready','leased','review','done','blocked',
                   'failed','budget_exhausted'));

-- 2. complete_task: каноническая семантика #3 (см. Issue #20).
--    F8: тело синхронизировано с schema/schema_v0.sql — расход учитывается
--    триггером ledger (llm_calls_spend_sync), а не прибавлением p_tokens здесь
--    (иначе двойной счёт); добавлен гейт по root_budget_cap.
create or replace function public.complete_task(p_task uuid, p_worker text,
                                                p_epoch bigint,
                                                p_result_ref text,
                                                p_tokens bigint default 0)
returns text language plpgsql as $$
declare v_new text; v_spent bigint; v_cap bigint; v_root_cap bigint;
        v_root_spent bigint; v_ledger bigint;
begin
  perform assert_worker_identity(p_worker);
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_tokens < 0 then
    raise exception 'tokens must be non-negative' using errcode = 'CT001';
  end if;
  if not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  -- F8: единый источник истины — ledger `llm_calls` (триггер llm_calls_spend_sync).
  select count(*) into v_ledger from llm_calls where task_id = p_task;
  if v_ledger = 0 and p_tokens > 0 then
    update tasks set spent_tokens = spent_tokens + p_tokens where id = p_task;
  end if;
  select spent_tokens, budget_cap, root_budget_cap
    into v_spent, v_cap, v_root_cap from tasks where id = p_task;
  v_new := case when v_spent > v_cap then 'budget_exhausted' else 'review' end;
  if v_new <> 'budget_exhausted' and v_root_cap is not null then
    select coalesce(sum(s.spent_tokens), 0) into v_root_spent
      from tasks s where s.root_id = (select root_id from tasks where id = p_task);
    if v_root_spent > v_root_cap then
      v_new := 'budget_exhausted';
    end if;
  end if;
  update tasks
     set state = v_new, result_ref = p_result_ref,
         lease_owner = null, lease_until = null, updated_at = now(),
         block_reason = case when v_new = 'budget_exhausted' then 'budget_exhausted' end
   where id = p_task;
  perform append_event(p_task, 'complete:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('ref', p_result_ref, 'new_state', v_new, 'tokens', p_tokens));
  return v_new;
end $$;

-- 3. Владелец и security definer (как в step2b/roles_2b.sql).
--    `create or replace function` сохраняет владельца и атрибуты, но задаём
--    явно — миграция должна быть самодостаточной и на БД без roles_2b.
alter function public.complete_task(uuid, text, bigint, text, bigint)
  owner to swarm_owner;
alter function public.complete_task(uuid, text, bigint, text, bigint)
  security definer set search_path = public, pg_temp;

-- Migration 006: review_candidates для роли swarm_reviewer (Issue #26). -- -- Проблема: в прод-контуре нет компонента, закрывающего `review -> done`. -- Ревьюеру нужны кандидаты (задачи в состоянии `review`) и путь к артефакту -- исполнителя, но `swarm_reviewer` имеет только EXECUTE на submit_review/ -- verify_chain и НЕ имеет SELECT на `tasks`/`artifacts` (least privilege). -- -- Решение: SECURITY DEFINER функция `review_candidates(limit)`, отдающая -- ровно то, что нужно ревьюеру: id, result_ref, contract, storage_path, -- created_by. Грант — только `swarm_reviewer`. -- -- Идемпотентно: create or replace + повторный grant безопасны.
create or replace function public.review_candidates(p_limit int default 10) returns table (id uuid, result_ref text, contract jsonb, storage_path text, created_by text) language sql stable as $$ select t.id, t.result_ref, t.contract, a.storage_path, a.created_by from tasks t left join artifacts a on a.task_id = t.id and a.ref = t.result_ref where t.state = 'review' order by t.updated_at asc, t.id limit least(greatest(p_limit, 1), 100) $$;
-- Владелец и режим исполнения — как у остальных витрин (step2/roles.sql §3-4). alter function public.review_candidates(int) owner to swarm_owner; alter function public.review_candidates(int) security definer set search_path = public, pg_temp;
-- Права: закрыть по умолчанию, выдать только ревьюеру. revoke all on function public.review_candidates(int) from public; grant execute on function public.review_candidates(int) to swarm_reviewer;
comment on function public.review_candidates(int) is 'Issue #26: кандидаты на ревью (id, result_ref, contract, storage_path, created_by) для swarm_reviewer';

-- Migration 007: http_status в cost ledger (Issue #2). -- -- Проблема: Issue #2 требует записывать HTTP-код каждого вызова LLM, но в -- `llm_calls` такой колонки не было. Статус кое-как зашивался в текстовое -- поле `error_code` (например, 'HTTP 401'), а у успешных вызовов HTTP-код не -- сохранялся вовсе — сверять «успех/ошибка» по коду было нельзя. -- -- Фикс: явная колонка `http_status int` (nullable: у transport/timeout/parse -- ошибок HTTP-кода нет — это честный NULL, а не выдуманный 0). -- -- Заполнение существующих строк: из `error_code` формата 'HTTP <code>'. -- Успешные вызовы (success = true) — 200. -- -- Идемпотентно: add column if not exists + update по условию.
alter table public.llm_calls add column if not exists http_status int;
comment on column public.llm_calls.http_status is 'Issue #2: HTTP-код вызова LLM (200 успех; 401/403/429/5xx ошибки; NULL — нет HTTP-ответа: transport/timeout/parse)';
-- Бэкфилл: успешные вызовы до появления колонки отвечали 200. update public.llm_calls set http_status = 200 where http_status is null and success;
-- Бэкфилл: ошибки с error_code вида 'HTTP 401' -> 401. update public.llm_calls set http_status = substring(error_code from 'HTTP ([0-9]{3})')::int where http_status is null and error_code ~ '^HTTP [0-9]{3}$';
-- Владелец — swarm_owner (инвариант каталога, см. migration 003). alter table public.llm_calls owner to swarm_owner;
-- Индекс для сверки: разрез по кодам ответа. create index if not exists llm_calls_http_status_idx on public.llm_calls (http_status) where http_status is not null;

-- Migration 008: сверка cost ledger с relay.fast (Issue #2). -- -- Проблема: локальный ledger (`llm_calls`) считает расход по оценкам цен -- (см. `llm_cost.rs`), а подтверждённый расход живёт только в web-интерфейсе -- relay.fast (публичного API баланса/usage нет). Расхождение локального и -- подтверждённого расхода нигде не фиксировалось, поэтому «оценка» могла -- незаметно разойтись с фактом. -- -- Решение: таблица снимков сверки + view последнего состояния. Каждый снимок -- хранит подтверждённый внешний расход, локальный расход на тот же момент, -- расхождение в процентах и признак устаревания (если relay.fast недоступен — -- переиспользуется последний подтверждённый снимок с `stale = true`). -- -- Идемпотентно: create table if not exists + create or replace view.
create table if not exists public.llm_cost_reconciliation ( id bigserial primary key, observed_at timestamptz not null default now(), source text not null default 'relay.fast/usage-logs/common', external_total_usd numeric(18,10) not null check (external_total_usd >= 0), local_total_usd numeric(18,10) not null check (local_total_usd >= 0), divergence_pct numeric(10,4) not null, stale boolean not null default false, note text );
create index if not exists llm_cost_reconciliation_observed_idx on public.llm_cost_reconciliation (observed_at desc);
comment on table public.llm_cost_reconciliation is 'Issue #2: снимки сверки локального cost ledger с подтверждённым расходом relay.fast'; comment on column public.llm_cost_reconciliation.divergence_pct is 'Issue #2: (local - external) / external * 100; >5% — требует разбора'; comment on column public.llm_cost_reconciliation.stale is 'Issue #2: true — relay.fast недоступен, показан последний подтверждённый снимок';
-- Последнее состояние сверки: свежий подтверждённый снимок + признак устаревания. create or replace view public.llm_cost_divergence as with latest_fresh as ( select * from public.llm_cost_reconciliation where not stale order by observed_at desc limit 1 ) select (select max(observed_at) from public.llm_cost_reconciliation) as last_attempt_at, lf.observed_at as confirmed_at, lf.external_total_usd as external_total_usd, lf.local_total_usd as local_total_usd, lf.divergence_pct as divergence_pct, (lf.id is null) as stale, abs(lf.divergence_pct) > 5 as alert from (select 1) one left join latest_fresh lf on true;
comment on view public.llm_cost_divergence is 'Issue #2: последнее подтверждённое состояние сверки; alert = расхождение >5%';
-- Владелец — swarm_owner (инвариант каталога, см. migration 003). alter table public.llm_cost_reconciliation owner to swarm_owner; alter sequence if exists public.llm_cost_reconciliation_id_seq owner to swarm_owner; alter view public.llm_cost_divergence owner to swarm_owner;
-- Чтение сверки — оператору и планировщику (как llm_costs_*), запись — сервисные роли. grant select on public.llm_cost_reconciliation to swarm_operator, swarm_planner; grant select on public.llm_cost_divergence to swarm_operator, swarm_planner, swarm_reviewer, swarm_watchdog; grant insert, select on public.llm_cost_reconciliation to swarm_operator; grant usage, select on sequence public.llm_cost_reconciliation_id_seq to swarm_operator;

-- Migration 009: базовая точка сверки cost ledger (Issue #2). -- -- Проблема: `total_usage` relay.fast (эндпоинт /v1/dashboard/billing/usage, -- проверено: HTTP 200, {"object":"list","total_usage":0.2342}) — накопительный -- за всё время жизни ключа, а локальный ledger считает расход только с момента -- своего появления. Прямое сравнение абсолютных сумм даёт ложное расхождение -- (вся история ключа против нескольких часов ledger) и вечный алерт. -- -- Фикс: сверка идёт по ОКНУ между снимками. Первый подтверждённый снимок — -- базовая точка (`is_baseline = true`, расхождение не считается); последующие -- сравнивают приращение внешнего расхода с приращением локального. -- -- Идемпотентно: add column if not exists + drop/create view.
alter table public.llm_cost_reconciliation add column if not exists window_external_usd numeric(18,10), add column if not exists window_local_usd numeric(18,10), add column if not exists is_baseline boolean not null default false;
comment on column public.llm_cost_reconciliation.window_external_usd is 'Issue #2: приращение подтверждённого расхода с предыдущего подтверждённого снимка'; comment on column public.llm_cost_reconciliation.window_local_usd is 'Issue #2: приращение локального расхода с предыдущего подтверждённого снимка'; comment on column public.llm_cost_reconciliation.is_baseline is 'Issue #2: базовая точка (первый подтверждённый снимок), расхождение не считается';
drop view if exists public.llm_cost_divergence;
create view public.llm_cost_divergence as with latest_fresh as ( select * from public.llm_cost_reconciliation where not stale order by observed_at desc, id desc limit 1 ) select (select max(observed_at) from public.llm_cost_reconciliation) as last_attempt_at, (select stale from public.llm_cost_reconciliation order by observed_at desc, id desc limit 1) as last_attempt_stale, lf.observed_at as confirmed_at, lf.external_total_usd as external_total_usd, lf.local_total_usd as local_total_usd, lf.window_external_usd as window_external_usd, lf.window_local_usd as window_local_usd, coalesce(lf.is_baseline, false) as is_baseline, lf.divergence_pct as divergence_pct, -- Issue #2: `stale` — признак УСТАРЕВШИХ данных, а не отсутствия подтверждённых -- снимков: он взводится, когда последняя попытка сверки не подтвердилась -- (relay.fast недоступен / отрицательное окно). Показывается последнее -- подтверждённое состояние + его timestamp + этот признак. ((select stale from public.llm_cost_reconciliation order by observed_at desc, id desc limit 1) is not false) as stale, -- Алерт только по окну: базовая точка и отсутствие подтверждённых снимков -- не алерят. (lf.id is not null and not coalesce(lf.is_baseline, false) and abs(lf.divergence_pct) > 5) as alert from (select 1) one left join latest_fresh lf on true;
comment on view public.llm_cost_divergence is 'Issue #2: последнее подтверждённое состояние сверки по окну; stale = последняя попытка не подтвердилась; alert = расхождение >5% (базовая точка не алертит)';
-- Владелец и гранты (см. 003/008). alter view public.llm_cost_divergence owner to swarm_owner; grant select on public.llm_cost_divergence to swarm_operator, swarm_planner, swarm_reviewer, swarm_watchdog;

-- Migration 010: витрина качества моделей (Issue #7/#10). -- -- Проблема: модель выбиралась по названию, а не по ИЗМЕРЕННОЙ цене успешного -- результата. Дешёвая модель, которая валится в `max_rework`, дороже дорогой, -- которая сдаёт с первого раза. Данные для измерения уже есть: `llm_calls` -- (модель + стоимость вызова) и `tasks` (терминальное состояние + `rework`). -- -- Решение: view `llm_model_quality`, агрегирующая по модели: -- - `tasks` — сколько задач с этой моделью дошло до терминала; -- - `tasks_done` — сколько из них `done`; -- - `success_rate` — доля успеха (done / tasks); -- - `total_cost_usd` — суммарный расход по модели (терминальные задачи); -- - `cost_per_success_usd` — **цена успешного результата** (расход / done); -- - `avg_rework` — среднее число доработок (косвенная мера качества). -- -- Именно `cost_per_success_usd` — метрика выбора для селектора -- (`crates/swarm-worker/src/model_selector.rs`); читается -- `scripts/model_quality_report.py` и кладётся в `SWARM_MODEL_STATS_FILE`. -- -- Права: view исполняется от владельца `swarm_owner` (как 003/008/009), поэтому -- worker-ролям не нужен прямой SELECT на `tasks`/`llm_calls` сверх уже выданного. -- -- Идемпотентно: create or replace view + повторный grant безопасны.
create or replace view public.llm_model_quality as with per_task as ( -- Расход по (модель, задача): одна задача могла уйти на несколько моделей, -- поэтому агрегируем именно пары, а не сумму по модели целиком. select c.model, c.task_id, sum(c.total_cost_usd) as task_cost_usd from public.llm_calls c group by c.model, c.task_id ), terminal as ( -- Только терминальные задачи: незавершённые искажали бы success_rate. select p.model, p.task_id, p.task_cost_usd, t.state, t.rework from per_task p join public.tasks t on t.id = p.task_id where t.state in ('done', 'blocked', 'failed', 'budget_exhausted') ) select model, count(*)::bigint as tasks, count(*) filter (where state = 'done')::bigint as tasks_done, case when count(*) > 0 then round((count(*) filter (where state = 'done'))::numeric / count(*), 4) else 0::numeric end as success_rate, coalesce(round(sum(task_cost_usd), 6), 0::numeric) as total_cost_usd, case when count(*) filter (where state = 'done') > 0 then round(sum(task_cost_usd) / (count(*) filter (where state = 'done')), 6) else null end as cost_per_success_usd, coalesce(round(avg(rework), 2), 0::numeric) as avg_rework from terminal group by model;
comment on view public.llm_model_quality is 'Issue #7/#10: качество модели по факту — tasks/tasks_done/success_rate и цена успешного результата (cost_per_success_usd)';
alter view public.llm_model_quality owner to swarm_owner; grant select on public.llm_model_quality to swarm_operator, swarm_planner, swarm_reviewer, swarm_watchdog;

-- Migration 011: бюджет ограничивает РЕАЛЬНЫЕ расходы (F8).
--
-- Дефект (аудит v0.4, docs/KNOWN_LIMITATIONS.md §5.10, F8):
--   `spent_tokens` рос ТОЛЬКО в `complete_task`. Воркер, получивший ответ LLM
--   (строка в `llm_calls` записана — деньги потрачены), но упавший/потерявший
--   аренду ДО `complete`, оставлял расход видимым в ledger и НЕвидимым в
--   `tasks.spent_tokens`. Цикл «взяли задачу → оплатили вызов → потеряли
--   аренду → reclaim_expired вернул в ready» крутился, пока
--   `attempts < budget.attempts`, и каждый оборот тратил деньги мимо бюджета.
--   Плюс `budget_cap` был только у задачи — суммарного лимита на дерево
--   (`root_id`) не существовало.
--
-- Фикс (директива владельца):
--   1. СИНХРОННЫЙ учёт: триггер AFTER INSERT ON llm_calls атомарно увеличивает
--      tasks.spent_tokens. Расход виден СРАЗУ, не дожидаясь complete.
--   2. ЕДИНЫЙ ИСТОЧНИК ИСТИНЫ: complete_task больше не прибавляет p_tokens
--      (иначе двойной счёт). Совместимость: если по задаче нет ни одной
--      строки ledger, а p_tokens > 0 (старый контракт вызова), учитываем
--      p_tokens ровно один раз.
--   3. ДВОЙНОЙ БЮДЖЕТНЫЙ ГЕЙТ: колонка tasks.root_budget_cap + проверка
--      SUM(spent_tokens) WHERE root_id = X < root_budget_cap в claim_task и
--      complete_task.
--   4. РЕКЛЕЙМ: reclaim_expired при исчерпанном бюджете (локальном или по
--      дереву) переводит задачу сразу в budget_exhausted, а не в ready.
--
-- Идемпотентно: add column if not exists, create or replace function,
-- drop trigger if exists + create. Безопасно применять повторно.
--
-- Замечание по триггеру и владельцу: триггерная функция — SECURITY DEFINER с
-- закреплённым search_path; обновление `tasks` идёт от имени swarm_owner, а не
-- от воркер-роли, поэтому INSERT в llm_calls под swarm_worker_w* не требует
-- прав на UPDATE tasks.

-- 1. Колонка root_budget_cap (см. schema_v0.sql).
alter table public.tasks
  add column if not exists root_budget_cap bigint
    check (root_budget_cap is null or root_budget_cap > 0);

comment on column public.tasks.root_budget_cap is
  'F8: суммарный бюджет дерева (root_id); у потомков денормализован триггером sync_root_budget';

-- 2. Синхронный учёт расхода: AFTER INSERT ON llm_calls -> tasks.spent_tokens.
create or replace function public.llm_calls_spend_sync() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  -- success=false (ошибка до ответа) несёт нулевые токены — UPDATE на 0
  -- безвреден. Учитываем и prompt, и completion: это реальные потраченные
  -- токены (модель могла сжечь промпт даже при обрыве ответа).
  update tasks
     set spent_tokens = spent_tokens + coalesce(new.prompt_tokens, 0)
                                     + coalesce(new.completion_tokens, 0),
         updated_at = now()
   where id = new.task_id;
  return new;
end $$;

alter function public.llm_calls_spend_sync() owner to swarm_owner;
revoke all on function public.llm_calls_spend_sync() from public;

drop trigger if exists llm_calls_spend_sync on public.llm_calls;
create trigger llm_calls_spend_sync
  after insert on public.llm_calls
  for each row execute function public.llm_calls_spend_sync();

-- 3. Денормализация root_budget_cap на дерево (см. schema_v0.sql).
create or replace function public.sync_root_budget() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_root bigint;
begin
  if new.root_id = new.id then
    return new;
  end if;
  select t.root_budget_cap into v_root from tasks t where t.id = new.root_id;
  new.root_budget_cap := v_root;
  return new;
end $$;

create or replace function public.propagate_root_budget() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.root_id = new.id and new.root_budget_cap is distinct from old.root_budget_cap then
    update tasks set root_budget_cap = new.root_budget_cap
     where root_id = new.id and id <> new.id;
  end if;
  return null;
end $$;

alter function public.sync_root_budget() owner to swarm_owner;
alter function public.propagate_root_budget() owner to swarm_owner;
revoke all on function public.sync_root_budget() from public;
revoke all on function public.propagate_root_budget() from public;

drop trigger if exists tasks_sync_root_budget on public.tasks;
create trigger tasks_sync_root_budget
  before insert or update of root_id, root_budget_cap on public.tasks
  for each row execute function public.sync_root_budget();

drop trigger if exists tasks_propagate_root_budget on public.tasks;
create trigger tasks_propagate_root_budget
  after update of root_budget_cap on public.tasks
  for each row execute function public.propagate_root_budget();

-- 4. add_task с явным root-бюджетом (см. schema_v0.sql).
create or replace function public.add_task(p_id uuid, p_root uuid, p_contract jsonb,
                                           p_budget_cap bigint, p_priority int default 0,
                                           p_root_budget_cap bigint default null)
returns void language plpgsql as $$
declare v_root uuid := coalesce(p_root, p_id); v_max numeric; v_cnt int; v_rbc bigint;
begin
  perform validate_contract(p_contract);
  perform lock_root(v_root);
  if p_root_budget_cap is not null and p_root_budget_cap <= 0 then
    raise exception 'root_budget_cap must be positive' using errcode = 'CT001';
  end if;
  if v_root <> p_id then
    select c_num(contract, '{budget,max_tasks}', 200) into v_max from tasks where id = v_root;
    if not found then raise exception 'root_not_found' using errcode = 'GR006'; end if;
    select count(*) into v_cnt from tasks where root_id = v_root;
    if v_cnt >= v_max then raise exception 'task_limit_exceeded' using errcode = 'GR004'; end if;
  end if;
  if v_root = p_id then
    v_rbc := p_root_budget_cap;
  else
    select root_budget_cap into v_rbc from tasks where id = v_root;
  end if;
  insert into tasks (id, root_id, contract, budget_cap, priority, root_budget_cap)
  values (p_id, v_root, p_contract, p_budget_cap, p_priority, v_rbc);
  perform append_event(p_id, 'created', 'created', 'planner',
                       jsonb_build_object('root', v_root, 'root_budget_cap', v_rbc));
end $$;

-- 5. claim_task: двойной бюджетный гейт (см. schema_v0.sql).
create or replace function public.claim_task(p_worker text, p_lease_sec int default 300)
returns table (out_task_id uuid, out_contract jsonb, out_epoch bigint,
               out_budget bigint, out_spent bigint)
language plpgsql as $$
declare v_id uuid; v_epoch bigint;
begin
  if p_lease_sec <= 0 then
    raise exception 'lease duration must be positive' using errcode = 'CT001';
  end if;
  -- F3: identity-проверка сохраняется (миграции применяются ПОСЛЕ
  -- roles_2b.sql, поэтому обязаны её воспроизвести, иначе create-or-replace
  -- тихо снимает защиту).
  perform assert_worker_identity(p_worker);
  update workers set last_seen = now() where id = p_worker;
  if not found then raise exception 'worker_unknown' using errcode = 'WK002'; end if;

  select t.id into v_id
  from tasks t join workers w on w.id = p_worker
  where t.state = 'ready'
    and t.spent_tokens < t.budget_cap
    and (t.root_budget_cap is null
         or (select coalesce(sum(s.spent_tokens), 0) from tasks s where s.root_id = t.root_id)
            < t.root_budget_cap)
    and t.attempts < c_num(t.contract, '{budget,attempts}', 3)
    and c_num(w.capabilities, '{ram_gb}', 0) >= c_num(t.contract, '{needs,min_ram_gb}', 0)
    and c_num(w.capabilities, '{models,coder_class}', 0) >= c_num(t.contract, '{needs,coder_class}', 0)
    and not exists (select 1 from task_deps d join tasks p on p.id = d.dep_id
                    where d.task_id = t.id and p.state <> 'done')
  order by (select count(*) from jsonb_array_elements_text(
              coalesce(t.contract #> '{needs,affinity_tags}', '[]'::jsonb)) x
            where x = any (w.affinity_tags)) desc,
           t.priority desc, t.created_at, t.id
  for update of t skip locked
  limit 1;

  if v_id is null then return; end if;

  update tasks
     set state = 'leased', lease_owner = p_worker, lease_epoch = lease_epoch + 1,
         lease_until = now() + make_interval(secs => p_lease_sec), updated_at = now()
   where id = v_id returning lease_epoch into v_epoch;
  perform append_event(v_id, 'claim:' || v_id || ':' || v_epoch, 'claimed', p_worker,
                       jsonb_build_object('epoch', v_epoch));
  return query select t.id, t.contract, t.lease_epoch, t.budget_cap, t.spent_tokens
               from tasks t where t.id = v_id;
end $$;

-- 5b. task_budget_state: свежее состояние бюджета для воркера (см. schema_v0.sql).
create or replace function public.task_budget_state(p_task uuid)
returns table (out_spent bigint, out_budget bigint,
               out_root_spent bigint, out_root_budget bigint)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_root uuid;
begin
  select root_id into v_root from tasks where id = p_task;
  if v_root is null then
    raise exception 'task_not_found' using errcode = 'GR000';
  end if;
  return query
    select t.spent_tokens, t.budget_cap,
           (select coalesce(sum(s.spent_tokens), 0)::bigint from tasks s where s.root_id = v_root),
           t.root_budget_cap
      from tasks t where t.id = p_task;
end $$;

alter function public.task_budget_state(uuid) owner to swarm_owner;
revoke all on function public.task_budget_state(uuid) from public;
grant execute on function public.task_budget_state(uuid) to swarm_worker;

-- 6. complete_task: без двойного счёта + гейт по дереву (см. schema_v0.sql).
create or replace function public.complete_task(p_task uuid, p_worker text,
                                                p_epoch bigint, p_result_ref text,
                                                p_tokens bigint default 0)
returns text language plpgsql as $$
declare v_new text; v_spent bigint; v_cap bigint; v_root_cap bigint;
        v_root_spent bigint; v_ledger bigint;
begin
  perform assert_worker_identity(p_worker);
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_tokens < 0 then
    raise exception 'tokens must be non-negative' using errcode = 'CT001';
  end if;
  if not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  -- FIND-CODE-04: фильтр по текущей эпохе (см. schema_v0.sql).
  select count(*) into v_ledger from llm_calls where task_id = p_task and lease_epoch = p_epoch;
  if v_ledger = 0 and p_tokens > 0 then
    update tasks set spent_tokens = spent_tokens + p_tokens where id = p_task;
  end if;
  select spent_tokens, budget_cap, root_budget_cap
    into v_spent, v_cap, v_root_cap from tasks where id = p_task;
  v_new := case when v_spent > v_cap then 'budget_exhausted' else 'review' end;
  if v_new <> 'budget_exhausted' and v_root_cap is not null then
    select coalesce(sum(s.spent_tokens), 0) into v_root_spent
      from tasks s where s.root_id = (select root_id from tasks where id = p_task);
    if v_root_spent > v_root_cap then
      v_new := 'budget_exhausted';
    end if;
  end if;
  update tasks
     set state = v_new, result_ref = p_result_ref,
         lease_owner = null, lease_until = null, updated_at = now(),
         block_reason = case when v_new = 'budget_exhausted' then 'budget_exhausted' end
   where id = p_task;
  perform append_event(p_task, 'complete:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('ref', p_result_ref, 'new_state', v_new, 'tokens', p_tokens));
  return v_new;
end $$;

-- 7. reclaim_expired: бюджет-осознанный реклейм (см. schema_v0.sql).
create or replace function public.reclaim_expired() returns int language plpgsql as $$
declare r record; v_n int := 0; v_next text; v_epoch bigint; v_root_spent bigint;
begin
  for r in
    select id, attempts, contract, spent_tokens, budget_cap, root_id, root_budget_cap
      from tasks
    where state = 'leased' and lease_until < now()
    order by id for update skip locked
  loop
    if r.spent_tokens >= r.budget_cap then
      v_next := 'budget_exhausted';
    elsif r.root_budget_cap is not null then
      select coalesce(sum(s.spent_tokens), 0) into v_root_spent
        from tasks s where s.root_id = r.root_id;
      if v_root_spent >= r.root_budget_cap then
        v_next := 'budget_exhausted';
      else
        v_next := case when r.attempts + 1 >= c_num(r.contract, '{budget,attempts}', 3)
                       then 'blocked' else 'ready' end;
      end if;
    else
      v_next := case when r.attempts + 1 >= c_num(r.contract, '{budget,attempts}', 3)
                     then 'blocked' else 'ready' end;
    end if;
    update tasks
       set state = v_next, attempts = attempts + 1, lease_epoch = lease_epoch + 1,
           lease_owner = null, lease_until = null, updated_at = now(),
           block_reason = case when v_next = 'blocked' then 'max_attempts'
                               when v_next = 'budget_exhausted' then 'budget_exhausted' end
     where id = r.id returning lease_epoch into v_epoch;
    perform append_event(r.id, 'reclaim:' || r.id || ':' || v_epoch, 'reclaimed', 'watchdog',
                         jsonb_build_object('new_state', v_next));
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- 8. Владелец и режим (инвариант каталога: не суперпользователь, search_path
--    закреплён; см. migration 003 и step2/test_roles.py::test_catalog_invariants).
alter function public.add_task(uuid, uuid, jsonb, bigint, int, bigint) owner to swarm_owner;
alter function public.claim_task(text, int) owner to swarm_owner;
alter function public.complete_task(uuid, text, bigint, text, bigint) owner to swarm_owner;
alter function public.reclaim_expired() owner to swarm_owner;

alter function public.add_task(uuid, uuid, jsonb, bigint, int, bigint)
  security definer set search_path = public, pg_temp;
alter function public.claim_task(text, int)
  security definer set search_path = public, pg_temp;
alter function public.complete_task(uuid, text, bigint, text, bigint)
  security definer set search_path = public, pg_temp;
alter function public.reclaim_expired()
  security definer set search_path = public, pg_temp;

-- Гранты не меняются: подписи add_task/claim_task/complete_task/reclaim_expired
-- сохранены (add_task получил лишь новый параметр со значением по умолчанию,
-- поэтому прежний вызов с 5 аргументами продолжает работать).
grant execute on function public.add_task(uuid, uuid, jsonb, bigint, int, bigint)
  to swarm_planner;
grant execute on function public.claim_task(text, int) to swarm_worker;
grant execute on function public.complete_task(uuid, text, bigint, text, bigint) to swarm_worker;
grant execute on function public.reclaim_expired() to swarm_watchdog;

-- Migration 012: контур обратной связи при доработке (FIND-CODE-02). -- -- Дефект (второй проход аудита, снимок 69f749b): -- При `changes_requested` ревьюер пишет причину отказа в `reviews.checks`, но -- воркер при повторном взятии задачи (`rework > 0`) её НЕ читает: `claim_task` -- возвращал только `(id, contract, epoch, budget, spent)`. Воркер отправлял в -- LLM ровно тот же промпт (та же температура), получал тот же ответ и снова -- не проходил приёмку — пока не упирался в `max_rework` (`blocked`) или -- `budget_cap` (`budget_exhausted`). Это корневая причина прод-статистики -- `changes_requested = 39` против `approved = 16`. -- -- Решение (вариант «отдельный RPC», а не новые колонки claim_task): -- Сигнатуру `claim_task` НЕ меняем. Смена возвращаемого типа требует -- `DROP FUNCTION` + перевыдачи гранта и ломает применение миграций -- (`create or replace` не меняет row type; migration 011 пересоздаёт -- claim_task со старой формой → «cannot change return type»). Вместо этого — -- отдельная SECURITY DEFINER функция `task_rework_feedback(task, worker, -- epoch)`, которую воркер вызывает сразу после выдачи аренды. Она проверяет -- ЖИВУЮ аренду (`assert_lease`), поэтому чужую диагностику не прочитать. -- -- Идемпотентно: create or replace + повторный grant безопасны.
create or replace function public.task_rework_feedback(p_task uuid, p_worker text, p_epoch bigint) returns table (out_rework int, out_last_review jsonb) language plpgsql security definer set search_path = public, pg_temp as $$ declare v_rework int; begin perform assert_lease(p_task, p_worker, p_epoch); select t.rework into v_rework from tasks t where t.id = p_task; if not found then raise exception 'task_not_found' using errcode = 'GR000'; end if; return query select v_rework, (select jsonb_build_object( 'verdict', r.verdict, 'artifact_ref', r.artifact_ref, 'checks', r.checks, 'reviewer', r.reviewer) from reviews r where r.task_id = p_task order by r.id desc limit 1); end $$;
-- Владелец и режим — канонический инвариант каталога -- (step2/test_roles.py::test_catalog_invariants). alter function public.task_rework_feedback(uuid, text, bigint) owner to swarm_owner; alter function public.task_rework_feedback(uuid, text, bigint) security definer set search_path = public, pg_temp;
-- Права: закрыть по умолчанию, выдать воркеру. revoke all on function public.task_rework_feedback(uuid, text, bigint) from public; grant execute on function public.task_rework_feedback(uuid, text, bigint) to swarm_worker;
comment on function public.task_rework_feedback(uuid, text, bigint) is 'FIND-CODE-02: диагностика последнего ревью (rework + verdict/checks) для возвращённой задачи';

-- Swarm dispatcher v0: Postgres 16. Единый источник истины.
-- Правила: любая запись воркера несёт lease_epoch (fencing); переход состояния и
-- событие в журнале пишутся в одной транзакции; время только через now() БД.
-- Коды ошибок: LS001 lease_lost, AR001 artifact_missing, CT001 contract_invalid,
-- GR000 task_not_found, GR001 cycle, GR002 depth, GR003 fanout, GR004 task_limit,
-- GR005 not_done, GR006 root_not_found, GR007 cross_root, GR008 not_pending,
-- GR009 not_blocked, RV001 review_stale, RV002 self_review, RV003 checks_failed,
-- WK001 worker_invalid, WK002 worker_unknown.

create table tasks (
  id           uuid primary key,
  root_id      uuid not null references tasks(id) deferrable initially deferred,
  state        text not null default 'pending'
               check (state in ('pending','ready','leased','review','done','blocked',
                                'failed','budget_exhausted')),
  contract     jsonb not null,
  lease_epoch  bigint not null default 0,
  lease_owner  text,
  lease_until  timestamptz,
  attempts     int not null default 0,          -- сбои воркера (истекшие аренды)
  rework       int not null default 0,          -- циклы после ревью
  budget_cap   bigint not null check (budget_cap > 0),
  spent_tokens bigint not null default 0,
  -- F8: суммарный бюджет всего дерева задач (root_id). Задаётся на корневой
  -- задаче (root_id = id) при add_task; у потомков денормализуется триггером
  -- sync_root_budget() и поддерживается равным корневому значению. NULL —
  -- лимита по дереву нет (обратная совместимость с задачами без явного
  -- root-бюджета). Гейты (claim_task, complete_task, reclaim_expired) сверяют
  -- SUM(spent_tokens) по root_id с этим значением.
  root_budget_cap bigint check (root_budget_cap is null or root_budget_cap > 0),
  result_ref   text,
  priority     int not null default 0,
  block_reason text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  -- инвариант аренды: leased <=> есть владелец и срок
  check ((state = 'leased') = (lease_owner is not null and lease_until is not null))
);
create index tasks_claim_idx  on tasks (priority desc, created_at) where state = 'ready';
create index tasks_root_idx   on tasks (root_id);
create index tasks_lease_idx  on tasks (lease_until) where state = 'leased';
create index tasks_pending_idx on tasks (id) where state = 'pending';

-- F8: денормализация root_budget_cap. Значение живёт на корневой задаче
-- (root_id = id); у потомков оно должно совпадать, чтобы гейты по дереву
-- (claim/complete/reclaim) могли одним запросом узнать лимит корня без
-- рекурсивного обхода. Триггер держит инвариант и при add_task, и при
-- изменении корневой задачи оператором (unblock_task поднимает budget_cap).
create function sync_root_budget() returns trigger language plpgsql as $$
declare v_root bigint;
begin
  if new.root_id = new.id then
    -- Сама корневая задача — источник истины.
    return new;
  end if;
  select t.root_budget_cap into v_root from tasks t where t.id = new.root_id;
  -- Корень ещё не вставлен? FK tasks.root_id отложен (deferrable initially
  -- deferred), поэтому в одной транзакции add_task(root) + add_task(child)
  -- порядок вставок может быть любым. Если корня ещё нет — оставляем NULL,
  -- последующий insert корня пересчитает потомков (см. ветку ниже).
  new.root_budget_cap := v_root;
  return new;
end $$;

create trigger tasks_sync_root_budget
  before insert or update of root_id, root_budget_cap on tasks
  for each row execute function sync_root_budget();

-- Обратная сторона: когда у корня задают/меняют root_budget_cap, разносим
-- значение по всем потомкам (иначе дерево осталось бы с устаревшим лимитом).
create function propagate_root_budget() returns trigger language plpgsql as $$
begin
  if new.root_id = new.id and new.root_budget_cap is distinct from old.root_budget_cap then
    update tasks set root_budget_cap = new.root_budget_cap
     where root_id = new.id and id <> new.id;
  end if;
  return null;
end $$;

create trigger tasks_propagate_root_budget
  after update of root_budget_cap on tasks
  for each row execute function propagate_root_budget();

create table artifacts (
  task_id      uuid not null references tasks(id),
  ref          text not null,                   -- 'sha256:...'
  created_by   text not null,
  lease_epoch  bigint not null,                 -- fencing-токен создателя
  content_type text,
  size_bytes   bigint,
  storage_path text not null,
  created_at   timestamptz not null default now(),
  primary key (task_id, ref)
);
alter table tasks add foreign key (id, result_ref) references artifacts (task_id, ref);

create table task_deps (
  task_id uuid not null references tasks(id) on delete cascade,
  dep_id  uuid not null references tasks(id) on delete cascade,
  primary key (task_id, dep_id),
  check (task_id <> dep_id)
);
create index task_deps_dep_idx on task_deps (dep_id);

create table workers (
  id            text primary key,
  capabilities  jsonb not null,                 -- {"ram_gb":16,"models":{"coder_class":2}}
  affinity_tags text[] not null default '{}',
  last_seen     timestamptz not null default now()
);
create index workers_seen_idx on workers (last_seen);

create table events (
  seq       bigserial primary key,
  task_id   uuid not null references tasks(id) on delete cascade,
  event_id  text not null,
  kind      text not null check (kind in ('created','dep_added','promoted','claimed',
            'artifact_saved','completed','review_submitted','reclaimed','reopened',
            'cascade_blocked','unblocked')),
  actor     text,
  payload   jsonb not null default '{}',
  at        timestamptz not null,
  prev_hash bytea,
  hash      bytea not null,
  unique (task_id, event_id)
);
create index events_task_idx on events (task_id, seq);

create table reviews (
  id           bigserial primary key,
  task_id      uuid not null,
  artifact_ref text not null,
  reviewer     text not null,
  verdict      text not null check (verdict in ('approved','changes_requested','rejected')),
  checks       jsonb not null,                  -- [{type,status,exit_code,log_ref,duration_ms}]
  created_at   timestamptz not null default now(),
  foreign key (task_id, artifact_ref) references artifacts (task_id, ref)
);

-- ---------- вспомогательные ----------
create function c_num(c jsonb, path text[], dflt numeric) returns numeric
language sql immutable as $$ select coalesce((c #>> path)::numeric, dflt) $$;

create function lock_root(p_root uuid) returns void
language sql as $$ select pg_advisory_xact_lock(hashtextextended(p_root::text, 0)) $$;

create function event_hash(p_prev bytea, p_task uuid, p_eid text, p_kind text,
                           p_actor text, p_payload jsonb, p_at timestamptz)
returns bytea language sql immutable as $$
  select sha256(coalesce(p_prev, '\x'::bytea) || convert_to(
    p_task::text || '|' || p_eid || '|' || p_kind || '|' || coalesce(p_actor, '') || '|' ||
    p_payload::text || '|' || to_char(p_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
    'UTF8')) $$;

-- Хэш-цепочка по задаче. Блокировка строки tasks сериализует запись, в том числе
-- первого события (у которого ещё нет строки events для блокировки).
create function append_event(p_task uuid, p_event_id text, p_kind text,
                             p_actor text, p_payload jsonb default '{}')
returns boolean language plpgsql as $$
declare v_prev bytea; v_at timestamptz := clock_timestamp();
begin
  perform 1 from tasks where id = p_task for update;
  if not found then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  if exists (select 1 from events where task_id = p_task and event_id = p_event_id) then
    return false;                                   -- идемпотентность
  end if;
  select hash into v_prev from events where task_id = p_task order by seq desc limit 1;
  insert into events (task_id, event_id, kind, actor, payload, at, prev_hash, hash)
  values (p_task, p_event_id, p_kind, p_actor, p_payload, v_at, v_prev,
          event_hash(v_prev, p_task, p_event_id, p_kind, p_actor, p_payload, v_at));
  return true;
end $$;

create function verify_chain(p_task uuid) returns boolean language plpgsql stable as $$
declare e record; v_prev bytea := null;
begin
  for e in select * from events where task_id = p_task order by seq loop
    if e.prev_hash is distinct from v_prev then return false; end if;
    if e.hash <> event_hash(v_prev, e.task_id, e.event_id, e.kind, e.actor, e.payload, e.at) then
      return false;
    end if;
    v_prev := e.hash;
  end loop;
  return true;
end $$;

create function validate_contract(c jsonb) returns void language plpgsql immutable as $$
declare k text; e jsonb;
begin
  if jsonb_typeof(c->'checks') is distinct from 'array' or jsonb_array_length(c->'checks') = 0 then
    raise exception 'contract_invalid: checks required' using errcode = 'CT001';
  end if;
  -- F15: каждый элемент checks — объект с непустым строковым type; id опционален,
  -- но если задан — непустая строка. Без этого задача без type не одобряется вечно.
  for e in select * from jsonb_array_elements(c->'checks') loop
    if jsonb_typeof(e) <> 'object'
       or jsonb_typeof(e->'type') is distinct from 'string' or btrim(e->>'type') = '' then
      raise exception 'contract_invalid: every check must be an object with non-empty string type'
        using errcode = 'CT001';
    end if;
    if jsonb_exists(e, 'id') and (jsonb_typeof(e->'id') <> 'string' or btrim(e->>'id') = '') then
      raise exception 'contract_invalid: check id must be a non-empty string' using errcode = 'CT001';
    end if;
  end loop;
  foreach k in array array['min_ram_gb','coder_class'] loop
    if jsonb_exists(c->'needs', k) and jsonb_typeof(c->'needs'->k) <> 'number' then
      raise exception 'contract_invalid: needs.% must be number', k using errcode = 'CT001';
    end if;
  end loop;
  if jsonb_exists(c->'needs', 'affinity_tags') and jsonb_typeof(c->'needs'->'affinity_tags') <> 'array' then
    raise exception 'contract_invalid: needs.affinity_tags must be array' using errcode = 'CT001';
  end if;
  foreach k in array array['attempts','max_rework','max_depth','max_children','max_tasks'] loop
    if jsonb_exists(c->'budget', k) and jsonb_typeof(c->'budget'->k) <> 'number' then
      raise exception 'contract_invalid: budget.% must be number', k using errcode = 'CT001';
    end if;
  end loop;
  -- F7: диапазоны. Тип-проверки выше пропускают абсурдные значения
  -- (attempts: 1000000, min_ram_gb: 1000000). Ограничиваем жёстко.
  if jsonb_exists(c->'budget', 'attempts')
     and ((c->'budget'->>'attempts')::numeric < 1
          or (c->'budget'->>'attempts')::numeric > 100) then
    raise exception 'contract_invalid: budget.attempts out of range 1..100' using errcode = 'CT001';
  end if;
  if jsonb_exists(c->'budget', 'max_rework')
     and ((c->'budget'->>'max_rework')::numeric < 0
          or (c->'budget'->>'max_rework')::numeric > 50) then
    raise exception 'contract_invalid: budget.max_rework out of range 0..50' using errcode = 'CT001';
  end if;
  -- FIND-NEW-03: max_depth/max_children/max_tasks раньше проверялись только на
  -- ТИП, но не на диапазон: `max_tasks: 0` блокировал дерево, `max_tasks: 1e9`
  -- снимал защиту от взрыва графа. Верхние границы — с запасом к дефолтам
  -- add_task (max_tasks 200, max_depth 10, max_children 20).
  if jsonb_exists(c->'budget', 'max_depth')
     and ((c->'budget'->>'max_depth')::numeric < 1
          or (c->'budget'->>'max_depth')::numeric > 50) then
    raise exception 'contract_invalid: budget.max_depth out of range 1..50' using errcode = 'CT001';
  end if;
  if jsonb_exists(c->'budget', 'max_children')
     and ((c->'budget'->>'max_children')::numeric < 1
          or (c->'budget'->>'max_children')::numeric > 100) then
    raise exception 'contract_invalid: budget.max_children out of range 1..100' using errcode = 'CT001';
  end if;
  if jsonb_exists(c->'budget', 'max_tasks')
     and ((c->'budget'->>'max_tasks')::numeric < 1
          or (c->'budget'->>'max_tasks')::numeric > 1000) then
    raise exception 'contract_invalid: budget.max_tasks out of range 1..1000' using errcode = 'CT001';
  end if;
  if jsonb_exists(c->'needs', 'min_ram_gb')
     and ((c->'needs'->>'min_ram_gb')::numeric < 0
          or (c->'needs'->>'min_ram_gb')::numeric > 1024) then
    raise exception 'contract_invalid: needs.min_ram_gb out of range 0..1024' using errcode = 'CT001';
  end if;
  if jsonb_exists(c->'needs', 'coder_class')
     and ((c->'needs'->>'coder_class')::numeric < 0
          or (c->'needs'->>'coder_class')::numeric > 100) then
    raise exception 'contract_invalid: needs.coder_class out of range 0..100' using errcode = 'CT001';
  end if;
  -- F7: реестр допустимых типов проверок и предел их числа.
  if jsonb_array_length(c->'checks') > 32 then
    raise exception 'contract_invalid: too many checks (max 32)' using errcode = 'CT001';
  end if;
  for e in select * from jsonb_array_elements(c->'checks') loop
    -- Волна 5.1: добавлен `unit`. F7 сузил реестр до cmd/test/lint/manual и тем
    -- сломал обратную совместимость: step2/test_review_gate.py использует
    -- {"type":"unit"}, и add_task начал падать с CT001. Набор типов теперь
    -- синхронизирован с Rust ALLOWED_CHECK_TYPES (N5).
    if lower(btrim(e->>'type')) not in ('cmd','test','unit','lint','manual') then
      raise exception 'contract_invalid: disallowed check type %', e->>'type' using errcode = 'CT001';
    end if;
  end loop;
end $$;

-- ---------- воркеры ----------
create function register_worker(p_id text, p_caps jsonb, p_tags text[] default '{}')
returns void language plpgsql as $$
begin
  if (p_caps ? 'ram_gb' and jsonb_typeof(p_caps->'ram_gb') <> 'number')
     or (p_caps #> '{models,coder_class}' is not null
         and jsonb_typeof(p_caps #> '{models,coder_class}') <> 'number') then
    raise exception 'worker_invalid' using errcode = 'WK001';
  end if;
  insert into workers (id, capabilities, affinity_tags, last_seen)
  values (p_id, p_caps, coalesce(p_tags, '{}'), now())
  on conflict (id) do update
    set capabilities = excluded.capabilities, affinity_tags = excluded.affinity_tags,
        last_seen = now();
end $$;

-- ---------- граф ----------
create function add_task(p_id uuid, p_root uuid, p_contract jsonb,
                         p_budget_cap bigint, p_priority int default 0,
                         p_root_budget_cap bigint default null)
returns void language plpgsql as $$
declare v_root uuid := coalesce(p_root, p_id); v_max numeric; v_cnt int; v_rbc bigint;
begin
  perform validate_contract(p_contract);
  perform lock_root(v_root);
  if p_root_budget_cap is not null and p_root_budget_cap <= 0 then
    raise exception 'root_budget_cap must be positive' using errcode = 'CT001';
  end if;
  if v_root <> p_id then
    select c_num(contract, '{budget,max_tasks}', 200) into v_max from tasks where id = v_root;
    if not found then raise exception 'root_not_found' using errcode = 'GR006'; end if;
    select count(*) into v_cnt from tasks where root_id = v_root;
    if v_cnt >= v_max then raise exception 'task_limit_exceeded' using errcode = 'GR004'; end if;
  end if;
  -- F8: у корня root_budget_cap задаётся явно (или наследуется от уже
  -- существующего корня при вставке потомка); у потомка — копия с корня.
  if v_root = p_id then
    v_rbc := p_root_budget_cap;
  else
    select root_budget_cap into v_rbc from tasks where id = v_root;
  end if;
  insert into tasks (id, root_id, contract, budget_cap, priority, root_budget_cap)
  values (p_id, v_root, p_contract, p_budget_cap, p_priority, v_rbc);
  perform append_event(p_id, 'created', 'created', 'planner',
                       jsonb_build_object('root', v_root, 'root_budget_cap', v_rbc));
end $$;

create function add_dep(p_task uuid, p_dep uuid) returns void language plpgsql as $$
declare v_root uuid; v_root2 uuid; v_state text; v_maxd numeric; v_maxc numeric; v_len int;
begin
  if p_task = p_dep then raise exception 'cycle_detected' using errcode = 'GR001'; end if;
  select root_id, state into v_root, v_state from tasks where id = p_task;
  select root_id into v_root2 from tasks where id = p_dep;
  if v_root is null or v_root2 is null then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  if v_root <> v_root2 then raise exception 'cross_root_dependency' using errcode = 'GR007'; end if;
  perform lock_root(v_root);                          -- сериализует конкурентные add_dep
  select state into v_state from tasks where id = p_task;
  if v_state <> 'pending' then raise exception 'task_not_pending' using errcode = 'GR008'; end if;

  if exists (
    with recursive d as (
      select task_id from task_deps where dep_id = p_task
      union
      select x.task_id from task_deps x join d on x.dep_id = d.task_id)
    select 1 from d where task_id = p_dep) then
    raise exception 'cycle_detected' using errcode = 'GR001';
  end if;

  select c_num(contract, '{budget,max_depth}', 10), c_num(contract, '{budget,max_children}', 20)
    into v_maxd, v_maxc from tasks where id = v_root;

  if (select count(*) from task_deps where dep_id = p_dep) >= v_maxc then
    raise exception 'fanout_exceeded' using errcode = 'GR003';
  end if;

  with recursive up(id, d) as (
    select p_dep, 0
    union
    select x.dep_id, up.d + 1 from task_deps x join up on x.task_id = up.id where up.d <= v_maxd),
  down(id, d) as (
    select p_task, 0
    union
    select x.task_id, down.d + 1 from task_deps x join down on x.dep_id = down.id where down.d <= v_maxd)
  select (select max(d) from up) + 1 + (select max(d) from down) into v_len;
  if v_len > v_maxd then raise exception 'depth_exceeded' using errcode = 'GR002'; end if;

  insert into task_deps (task_id, dep_id) values (p_task, p_dep);
  perform append_event(p_task, 'dep:' || p_dep, 'dep_added', 'planner', jsonb_build_object('dep', p_dep));
end $$;

create function promote_ready() returns int language plpgsql as $$
declare r record; v_n int := 0; v_epoch bigint;
begin
  for r in
    select t.id from tasks t
    where t.state = 'pending'
      and not exists (select 1 from task_deps d join tasks p on p.id = d.dep_id
                      where d.task_id = t.id and p.state <> 'done')
    order by t.id for update skip locked
  loop
    update tasks set state = 'ready', updated_at = now() where id = r.id
      returning lease_epoch into v_epoch;
    perform append_event(r.id, 'promote:' || r.id || ':' || v_epoch, 'promoted', 'scheduler');
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- ---------- жизненный цикл воркера ----------
create function claim_task(p_worker text, p_lease_sec int default 300)
returns table (out_task_id uuid, out_contract jsonb, out_epoch bigint,
               out_budget bigint, out_spent bigint)
language plpgsql as $$
declare v_id uuid; v_epoch bigint;
begin
  if p_lease_sec <= 0 then
    raise exception 'lease duration must be positive' using errcode = 'CT001';
  end if;
  update workers set last_seen = now() where id = p_worker;
  if not found then raise exception 'worker_unknown' using errcode = 'WK002'; end if;

  select t.id into v_id
  from tasks t join workers w on w.id = p_worker
  where t.state = 'ready'
    -- F8: ДВОЙНОЙ бюджетный гейт.
    --   1) локальный: задача не исчерпала собственный budget_cap;
    --   2) по дереву: сумма spent_tokens по root_id меньше root_budget_cap
    --      (если он задан). Так расход «соседей» по дереву останавливает
    --      выдачу, даже когда у самой задачи локальный бюджет ещё есть.
    and t.spent_tokens < t.budget_cap
    and (t.root_budget_cap is null
         or (select coalesce(sum(s.spent_tokens), 0) from tasks s where s.root_id = t.root_id)
            < t.root_budget_cap)
    and t.attempts < c_num(t.contract, '{budget,attempts}', 3)
    and c_num(w.capabilities, '{ram_gb}', 0) >= c_num(t.contract, '{needs,min_ram_gb}', 0)
    and c_num(w.capabilities, '{models,coder_class}', 0) >= c_num(t.contract, '{needs,coder_class}', 0)
    and not exists (select 1 from task_deps d join tasks p on p.id = d.dep_id
                    where d.task_id = t.id and p.state <> 'done')
  order by (select count(*) from jsonb_array_elements_text(
              coalesce(t.contract #> '{needs,affinity_tags}', '[]'::jsonb)) x
            where x = any (w.affinity_tags)) desc,
           t.priority desc, t.created_at, t.id
  for update of t skip locked
  limit 1;

  if v_id is null then return; end if;

  update tasks
     set state = 'leased', lease_owner = p_worker, lease_epoch = lease_epoch + 1,
         lease_until = now() + make_interval(secs => p_lease_sec), updated_at = now()
   where id = v_id returning lease_epoch into v_epoch;
  perform append_event(v_id, 'claim:' || v_id || ':' || v_epoch, 'claimed', p_worker,
                       jsonb_build_object('epoch', v_epoch));
  return query select t.id, t.contract, t.lease_epoch, t.budget_cap, t.spent_tokens
               from tasks t where t.id = v_id;
end $$;

-- F8: актуальное состояние бюджета задачи для воркера.
--
-- `Lease.spent_tokens` — снимок на момент claim и не видит расход, сделанный
-- ПОСЛЕ выдачи (в т.ч. другим воркером по тому же дереву). Перед вызовом LLM
-- воркер читает свежие значения (локальный лимит + суммарный по дереву), чтобы
-- остановиться до траты денег. SECURITY DEFINER: роли воркера прямой SELECT к
-- tasks закрыт.
create function task_budget_state(p_task uuid)
returns table (out_spent bigint, out_budget bigint,
               out_root_spent bigint, out_root_budget bigint)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_root uuid;
begin
  select root_id into v_root from tasks where id = p_task;
  if v_root is null then
    raise exception 'task_not_found' using errcode = 'GR000';
  end if;
  return query
    select t.spent_tokens, t.budget_cap,
           (select coalesce(sum(s.spent_tokens), 0)::bigint from tasks s where s.root_id = v_root),
           t.root_budget_cap
      from tasks t where t.id = p_task;
end $$;

-- FIND-CODE-02: контур обратной связи при доработке.
--
-- Ревьюер при `changes_requested` пишет причину в `reviews.checks`, но воркер
-- её не читал (claim_task отдавал только контракт) → перегенерировал то же
-- решение вслепую (корень `changes_requested = 39` на проде).
--
-- Возвращает число возвратов и диагностику последнего ревью. Требует ЖИВУЮ
-- аренду (`assert_lease`) и identity воркера — чужую диагностику не прочитать.
create function task_rework_feedback(p_task uuid, p_worker text, p_epoch bigint)
returns table (out_rework int, out_last_review jsonb)
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_rework int;
begin
  perform assert_lease(p_task, p_worker, p_epoch);
  select t.rework into v_rework from tasks t where t.id = p_task;
  if not found then
    raise exception 'task_not_found' using errcode = 'GR000';
  end if;
  return query
    select v_rework,
           (select jsonb_build_object(
                     'verdict', r.verdict,
                     'artifact_ref', r.artifact_ref,
                     'checks', r.checks,
                     'reviewer', r.reviewer)
              from reviews r
             where r.task_id = p_task
             order by r.id desc
             limit 1);
end $$;

-- Продлевает только действующую аренду; истёкшую «оживить» нельзя.
create function heartbeat(p_task uuid, p_worker text, p_epoch bigint, p_extend_sec int default 300)
returns boolean language plpgsql as $$
begin
  if p_extend_sec <= 0 then
    raise exception 'lease extension must be positive' using errcode = 'CT001';
  end if;
  update tasks set lease_until = now() + make_interval(secs => p_extend_sec), updated_at = now()
   where id = p_task and state = 'leased' and lease_owner = p_worker
     and lease_epoch = p_epoch and lease_until > now();
  if found then update workers set last_seen = now() where id = p_worker; end if;
  return found;
end $$;

create function assert_lease(p_task uuid, p_worker text, p_epoch bigint) returns void
language plpgsql as $$
begin
  perform 1 from tasks
   where id = p_task and state = 'leased' and lease_owner = p_worker
     and lease_epoch = p_epoch and lease_until > now()
   for update;
  if not found then raise exception 'lease_lost' using errcode = 'LS001'; end if;
end $$;

create function save_artifact(p_task uuid, p_worker text, p_epoch bigint, p_ref text,
                              p_storage text, p_content_type text default null,
                              p_size bigint default null)
returns void language plpgsql as $$
begin
  perform assert_lease(p_task, p_worker, p_epoch);
  insert into artifacts (task_id, ref, created_by, lease_epoch, content_type, size_bytes, storage_path)
  values (p_task, p_ref, p_worker, p_epoch, p_content_type, p_size, p_storage)
  on conflict (task_id, ref) do update
     set created_by = excluded.created_by, lease_epoch = excluded.lease_epoch,
         content_type = excluded.content_type, size_bytes = excluded.size_bytes,
         storage_path = excluded.storage_path, created_at = now();
  -- FIND-NEW-02: `lease_epoch` в ключе. Без него повторное сохранение того же ref
  -- на новой эпохе давало коллизию event_id, append_event тихо возвращал false,
  -- и переход состояния оставался без следа в хэш-цепочке events.
  perform append_event(p_task, 'art:' || p_epoch || ':' || p_ref, 'artifact_saved', p_worker,
                       jsonb_build_object('ref', p_ref));
end $$;

create function complete_task(p_task uuid, p_worker text, p_epoch bigint,
                              p_result_ref text, p_tokens bigint default 0)
returns text language plpgsql as $$
declare v_new text; v_spent bigint; v_cap bigint; v_root_cap bigint;
        v_root_spent bigint; v_ledger bigint;
begin
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_tokens < 0 then
    raise exception 'tokens must be non-negative' using errcode = 'CT001';
  end if;
  if not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  -- F8: единый источник истины по расходу — ledger `llm_calls` (триггер
  -- `llm_calls_spend_sync`). complete_task больше НЕ прибавляет p_tokens
  -- повторно, иначе расход считался бы дважды. Совместимость: если по
  -- задаче ещё нет ни одной строки ledger, а p_tokens > 0 (старый контракт
  -- вызова, напр. прямые тесты), учитываем p_tokens ровно один раз здесь.
  -- FIND-CODE-04: фильтр по ТЕКУЩЕЙ эпохе. Без `and lease_epoch = p_epoch`
  -- любая запись ledger за прошлые эпохи навсегда делала v_ledger > 0, и
  -- p_tokens новой эпохи молча терялся (расход занижался).
  select count(*) into v_ledger from llm_calls where task_id = p_task and lease_epoch = p_epoch;
  if v_ledger = 0 and p_tokens > 0 then
    update tasks set spent_tokens = spent_tokens + p_tokens where id = p_task;
  end if;
  select spent_tokens, budget_cap, root_budget_cap
    into v_spent, v_cap, v_root_cap from tasks where id = p_task;
  v_new := case when v_spent > v_cap then 'budget_exhausted' else 'review' end;
  -- F8: гейт по дереву. Даже когда локальный бюджет цел, превышение
  -- суммарного root-бюджета отправляет задачу в budget_exhausted.
  if v_new <> 'budget_exhausted' and v_root_cap is not null then
    select coalesce(sum(s.spent_tokens), 0) into v_root_spent
      from tasks s where s.root_id = (select root_id from tasks where id = p_task);
    if v_root_spent > v_root_cap then
      v_new := 'budget_exhausted';
    end if;
  end if;
  update tasks
     set state = v_new, result_ref = p_result_ref,
         lease_owner = null, lease_until = null, updated_at = now(),
         block_reason = case when v_new = 'budget_exhausted' then 'budget_exhausted' end
   where id = p_task;
  perform append_event(p_task, 'complete:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('ref', p_result_ref, 'new_state', v_new, 'tokens', p_tokens));
  return v_new;
end $$;

-- F4: честный отказ воркера. Раньше не-транзиентная ошибка LLM выставлялась
-- через complete_task() с подделанным overspend (worker.rs), чтобы SQL сам
-- перевёл задачу в blocked. Это ложь в журнале (spent_tokens врёт) и хрупко:
-- зависит от '>' в complete_task. Теперь отказ — явная операция с reason.
create function fail_task(p_task uuid, p_worker text, p_epoch bigint,
                          p_result_ref text, p_reason text) returns text
language plpgsql as $$
begin
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_result_ref is not null
     and not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  update tasks
     set state = 'blocked', result_ref = coalesce(p_result_ref, result_ref),
         lease_owner = null, lease_until = null,
         block_reason = left('llm_error: ' || coalesce(p_reason, ''), 500), updated_at = now()
   where id = p_task;
  perform append_event(p_task, 'fail:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('failed', true, 'reason', left(coalesce(p_reason, ''), 500)));
  return 'blocked';
end $$;

-- Issue #3: отказ воркера с явным целевым состоянием.
-- `fail_task` всегда даёт 'blocked'; здесь состояние выбирает вызывающий:
--   * 'budget_exhausted' — исчерпан бюджет (токен-лимит или глобальный),
--   * 'failed'          — сбой авторизации (401/403), нужна ротация ключа.
-- Семантика аренды та же (assert_lease), причина — в block_reason и в журнале.
create function fail_task_state(p_task uuid, p_worker text, p_epoch bigint,
                                p_result_ref text, p_reason text, p_state text)
returns text language plpgsql as $$
begin
  if p_state not in ('failed', 'budget_exhausted', 'blocked') then
    raise exception 'invalid target state %', p_state using errcode = 'CT001';
  end if;
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_result_ref is not null
     and not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  update tasks
     set state = p_state, result_ref = coalesce(p_result_ref, result_ref),
         lease_owner = null, lease_until = null,
         block_reason = left(coalesce(p_reason, ''), 500), updated_at = now()
   where id = p_task;
  perform append_event(p_task, 'fail:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('failed', true, 'state', p_state,
                                          'reason', left(coalesce(p_reason, ''), 500)));
  return p_state;
end $$;

create function submit_review(p_task uuid, p_ref text, p_reviewer text,
                              p_verdict text, p_checks jsonb)
returns text language plpgsql security definer set search_path = public, pg_temp as $$
declare t tasks%rowtype; v_creator text; v_new text;
begin
  select * into t from tasks where id = p_task for update;
  if not found then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  if t.state <> 'review' or t.result_ref is distinct from p_ref then
    raise exception 'review_stale' using errcode = 'RV001';  -- ревью строго привязано к хэшу
  end if;
  select created_by into v_creator from artifacts where task_id = p_task and ref = p_ref;
  if v_creator = p_reviewer then raise exception 'self_review' using errcode = 'RV002'; end if;
  if p_verdict = 'approved' then
    if jsonb_typeof(p_checks) <> 'array' then
      raise exception 'checks_failed' using errcode = 'RV003';
    end if;
    -- Строгий review-gate (F2, вариант A): ключ проверки =
    --   coalesce(id, type || '|' || run).
    -- Для каждого ключа число pass в отчёте >= числа требований контракта с этим
    -- ключом. Сопоставление только по type обходилось: контракт с двумя cmd
    -- (cargo test, cargo clippy) закрывался одним generic {"type":"cmd","status":"pass"}.
    -- Учёт run разводит такие проверки на разные ключи.
    if exists (
      select 1 from (
        select coalesce(c->>'id', (c->>'type') || '|' || coalesce(c->>'run', '')) as k,
               count(*) as n
          from jsonb_array_elements(coalesce(t.contract->'checks', '[]'::jsonb)) c
         group by 1) req
       where (select count(*) from jsonb_array_elements(p_checks) p
               where coalesce(p->>'id', (p->>'type') || '|' || coalesce(p->>'run', '')) = req.k
                 and p->>'status' = 'pass') < req.n
    ) then
      raise exception 'checks_failed' using errcode = 'RV003';
    end if;
  end if;
  insert into reviews (task_id, artifact_ref, reviewer, verdict, checks)
  values (p_task, p_ref, p_reviewer, p_verdict, p_checks);

  if p_verdict = 'approved' then v_new := 'done';
  elsif p_verdict = 'changes_requested' then
    v_new := case when t.rework + 1 > c_num(t.contract, '{budget,max_rework}', 3)
                  then 'blocked' else 'ready' end;
  else v_new := 'blocked';
  end if;

  update tasks
     set state = v_new,
         rework = rework + case when p_verdict = 'changes_requested' then 1 else 0 end,
         lease_epoch = lease_epoch + case when v_new = 'ready' then 1 else 0 end,
         block_reason = case when v_new = 'blocked' then
                        case when p_verdict = 'rejected' then 'rejected' else 'max_rework' end end,
         updated_at = now()
   where id = p_task;
  -- FIND-NEW-02: `t.lease_epoch` в ключе события. Без него повторное ревью того
  -- же ref после reopen (или детерминированная пересборка на новой эпохе) давало
  -- коллизию event_id, append_event тихо возвращал false, и переход состояния
  -- оставался БЕЗ следа в хэш-цепочке events. Эпоха растёт на +1 в claim_task,
  -- поэтому ключ всегда уникален.
  perform append_event(p_task, 'review:' || t.lease_epoch || ':' || p_ref || ':' || p_reviewer,
                       'review_submitted',
                       p_reviewer, jsonb_build_object('verdict', p_verdict, 'new_state', v_new));
  if v_new = 'done' then perform promote_ready(); end if;
  return v_new;
end $$;

-- ---------- сторож и операторские действия ----------
-- attempts растёт только здесь; epoch+1 отсекает зомби-воркера немедленно.
create function reclaim_expired() returns int language plpgsql as $$
declare r record; v_n int := 0; v_next text; v_epoch bigint; v_root_spent bigint;
begin
  for r in
    select id, attempts, contract, spent_tokens, budget_cap, root_id, root_budget_cap
      from tasks
    where state = 'leased' and lease_until < now()
    order by id for update skip locked
  loop
    -- F8: если воркер успел оплатить LLM-вызов, но упал до complete,
    -- расход уже лежит в spent_tokens (триггер ledger). Возвращать такую
    -- задачу в ready бессмысленно — она тут же исчерпает бюджет заново.
    -- Переводим сразу в budget_exhausted (локальный лимит или по дереву).
    if r.spent_tokens >= r.budget_cap then
      v_next := 'budget_exhausted';
    elsif r.root_budget_cap is not null then
      select coalesce(sum(s.spent_tokens), 0) into v_root_spent
        from tasks s where s.root_id = r.root_id;
      if v_root_spent >= r.root_budget_cap then
        v_next := 'budget_exhausted';
      else
        v_next := case when r.attempts + 1 >= c_num(r.contract, '{budget,attempts}', 3)
                       then 'blocked' else 'ready' end;
      end if;
    else
      v_next := case when r.attempts + 1 >= c_num(r.contract, '{budget,attempts}', 3)
                     then 'blocked' else 'ready' end;
    end if;
    update tasks
       set state = v_next, attempts = attempts + 1, lease_epoch = lease_epoch + 1,
           lease_owner = null, lease_until = null, updated_at = now(),
           block_reason = case when v_next = 'blocked' then 'max_attempts'
                               when v_next = 'budget_exhausted' then 'budget_exhausted' end
     where id = r.id returning lease_epoch into v_epoch;
    perform append_event(r.id, 'reclaim:' || r.id || ':' || v_epoch, 'reclaimed', 'watchdog',
                         jsonb_build_object('new_state', v_next));
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

create function reopen_task(p_task uuid, p_actor text) returns int
language plpgsql as $$
declare r record; v_n int := 0; v_epoch bigint; v_root uuid;
begin
  select root_id into v_root from tasks where id = p_task;
  if v_root is null then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  perform lock_root(v_root);
  update tasks set state = 'ready', lease_epoch = lease_epoch + 1, lease_owner = null,
         lease_until = null, block_reason = null, updated_at = now()
   where id = p_task and state = 'done' returning lease_epoch into v_epoch;
  if not found then raise exception 'not_done' using errcode = 'GR005'; end if;
  perform append_event(p_task, 'reopen:' || p_task || ':' || v_epoch, 'reopened', p_actor);
  for r in
    with recursive sub as (
      select task_id from task_deps where dep_id = p_task
      union
      select d.task_id from task_deps d join sub s on d.dep_id = s.task_id)
    select t.id from tasks t
    where t.id in (select task_id from sub) and t.state in ('ready','leased','review','done')
    order by t.id for update
  loop
    update tasks set state = 'blocked', lease_owner = null, lease_until = null,
           lease_epoch = lease_epoch + 1, block_reason = 'parent_reopened', updated_at = now()
     where id = r.id returning lease_epoch into v_epoch;
    perform append_event(r.id, 'cascade:' || r.id || ':' || v_epoch, 'cascade_blocked', p_actor,
                         jsonb_build_object('parent', p_task));
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- F4: восстановимый unblock. Раньше задача из blocked возвращалась без учёта
-- бюджета: если он уже исчерпан, unblock не помогал — задача снова уходила в
-- blocked на первом же complete. Теперь оператор может явно поднять
-- budget_cap, а при исчерпанном бюджете без явного cap функция отказывает
-- (CT001) — вместо тихого нерабочего разблокирования.
create function unblock_task(p_task uuid, p_actor text, p_new_budget_cap bigint default null)
returns text language plpgsql as $$
declare v_epoch bigint; t tasks%rowtype;
begin
  select * into t from tasks where id = p_task
    and state in ('blocked', 'failed', 'budget_exhausted') for update;
  if not found then raise exception 'not_blocked' using errcode = 'GR009'; end if;
  if p_new_budget_cap is not null then
    if p_new_budget_cap <= t.spent_tokens then
      raise exception 'budget cap must exceed spent_tokens' using errcode = 'CT001';
    end if;
  elsif t.spent_tokens >= t.budget_cap then
    raise exception 'budget_exhausted: pass p_new_budget_cap' using errcode = 'CT001';
  end if;
  update tasks set state = 'pending', attempts = 0, rework = 0, block_reason = null,
         lease_epoch = lease_epoch + 1, budget_cap = coalesce(p_new_budget_cap, budget_cap),
         updated_at = now()
   where id = p_task returning lease_epoch into v_epoch;
  perform append_event(p_task, 'unblock:' || p_task || ':' || v_epoch, 'unblocked', p_actor,
                       jsonb_build_object('new_budget_cap', p_new_budget_cap));
  perform promote_ready();
  return (select state from tasks where id = p_task);
end $$;

#!/bin/sh # 02-roles.sh — применяет roles.sql после 01-schema.sql. # # Запускается официальным образом postgres из /docker-entrypoint-initdb.d/ # только при пустом каталоге данных (первая инициализация). # Пароли ролей берутся из env (SWARM_PW_*), заданы в docker-compose.yml. set -eu
: "${POSTGRES_USER:?POSTGRES_USER required}" : "${POSTGRES_DB:?POSTGRES_DB required}"
psql -v ON_ERROR_STOP=1 \ -U "$POSTGRES_USER" -d "$POSTGRES_DB" \ -v worker_pw="$SWARM_PW_WORKER" \ -v watchdog_pw="$SWARM_PW_WATCHDOG" \ -v planner_pw="$SWARM_PW_PLANNER" \ -v reviewer_pw="$SWARM_PW_REVIEWER" \ -v operator_pw="$SWARM_PW_OPERATOR" \ -v cli_pw="$SWARM_PW_CLI" \ -f /sql/roles.sql

#!/bin/sh # 03-role-patches.sh — применяет патчи грантов после roles.sql и roles_2b.sql. # # Запускается официальным образом postgres из /docker-entrypoint-initdb.d/ # только при пустом каталоге данных (первая инициализация). # # Порядок инициализации: # 01-schema.sql (schema/schema_v0.sql) # 02-roles.sh (step2/roles.sql) # 03-roles-2b.sh (step2b/roles_2b.sql) # 04-role-patches.sh (этот файл; step2/roles_patch_*.sql) # # roles.sql и roles_2b.sql не меняются (приняты). Новые гранты добавляются # отдельными патч-файлами вида step2/roles_patch_*.sql и подключаются здесь. set -eu
: "${POSTGRES_USER:?POSTGRES_USER required}" : "${POSTGRES_DB:?POSTGRES_DB required}"
for patch in /sql/roles_patch_*.sql; do [ -e "$patch" ] || continue echo "03-role-patches: applying $patch" psql -v ON_ERROR_STOP=1 \ -U "$POSTGRES_USER" -d "$POSTGRES_DB" \ -f "$patch" done

#!/bin/sh # 03-roles-2b.sh — применяет step2b/roles_2b.sql (идентификация воркера) # после roles.sql. # # Запускается официальным образом postgres из /docker-entrypoint-initdb.d/ # только при пустом каталоге данных (первая инициализация). # # Порядок инициализации: # 01-schema.sql (schema/schema_v0.sql) # 02-roles.sh (step2/roles.sql) # 03-roles-2b.sh (этот файл; step2b/roles_2b.sql) # 04-role-patches.sh (step2/roles_patch_*.sql) set -eu
: "${POSTGRES_USER:?POSTGRES_USER required}" : "${POSTGRES_DB:?POSTGRES_DB required}"
psql -v ON_ERROR_STOP=1 \ -U "$POSTGRES_USER" -d "$POSTGRES_DB" \ -v w1_pw="$SWARM_PW_W1" \ -v w2_pw="$SWARM_PW_W2" \ -v w_1_pw="$SWARM_PW_W_1" \ -v gpu_1_pw="$SWARM_PW_GPU_1" \ -f /sql/roles_2b.sql

#!/bin/sh # 05-migrations.sh — применяет schema/migrations/*.sql после ролей. # # Запускается официальным образом postgres из /docker-entrypoint-initdb.d/ # только при пустой инициализации данных. Порядок — лексикографический по имени # файла (001_, 002_, ...). # # Раньше миграции (001_llm_calls.sql) применялись только вручную, поэтому на # свежей БД таблица llm_calls отсутствовала, а workers молча теряли метрики # (Issue #9, #11). Теперь они применяются автоматически при первом старте. set -eu
: "${POSTGRES_USER:?POSTGRES_USER required}" : "${POSTGRES_DB:?POSTGRES_DB required}"
for f in /sql/migrations/*.sql; do [ -e "$f" ] || continue echo "[migrations] applying $(basename "$f")" psql -v ON_ERROR_STOP=1 \ -U "$POSTGRES_USER" -d "$POSTGRES_DB" \ -f "$f" done

#!/usr/bin/env bash # Disposable acceptance harness for the schema/RBAC acceptance branch. # This file intentionally does not use docker compose: the database has no # named volume and is removed by the EXIT trap on every path. set -Eeuo pipefail
BASE="" BRANCH="HEAD" WORKTREE="$(pwd)" SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)" FULL_WORKSPACE_TEST=0 ALLOW_BLOCKED=0 LOG_DIR="${TMPDIR:-/tmp}/swarm-dispatcher-acceptance" CONTAINER="" DB_PASSWORD="" LOG_FILE="" SEALED_LOG_FILE="" ATTESTATION_FILE="" EVENT_FILE="" TEST_NAMES_FILE="" ALLOWLIST_FILE="" FAILURES=0 BLOCKED_COUNT=0 DB_READY=0 TEST_DATABASE_URL="" SANITIZED_TEST_DATABASE_URL="" TEST_DB_HOST="127.0.0.1" TEST_DB_PORT="" TEST_DB_NAME="c2_swarm" TEST_DB_USER="postgres" CREDENTIALS_REDACTED=0
usage() { cat <<'USAGE' Usage: scripts/acceptance_harness.sh --base COMMIT [options]
Options: --base COMMIT Required diff comparison base. --branch REF Ref to check (default: HEAD). --worktree PATH Checkout to inspect (default: current directory). --allowlist-file PATH Exact paths/prefixes (path or path/*, one per line). --log-dir PATH Temporary log directory. --full-workspace-test Require and run cargo test --workspace (release requirement). --allow-blocked Diagnostic mode: allow BLOCKED checks and mark gate CONDITIONAL.
Default is a STRICT release gate: omitting --full-workspace-test records that check as BLOCKED and exits nonzero. Use --allow-blocked only for diagnostics. -h, --help Show this help. USAGE }
while (($#)); do case "$1" in --base) BASE="${2:?--base requires a commit}"; shift 2 ;; --branch) BRANCH="${2:?--branch requires a ref}"; shift 2 ;; --worktree) WORKTREE="${2:?--worktree requires a path}"; shift 2 ;; --allowlist-file) ALLOWLIST_FILE="${2:?--allowlist-file requires a path}"; shift 2 ;; --log-dir) LOG_DIR="${2:?--log-dir requires a path}"; shift 2 ;; --full-workspace-test) FULL_WORKSPACE_TEST=1; shift ;; --allow-blocked) ALLOW_BLOCKED=1; shift ;; -h|--help) usage; exit 0 ;; *) echo "FAIL unknown option: $1" >&2; usage >&2; exit 2 ;; esac done
if [[ -z "$BASE" ]]; then echo "FAIL --base is required" >&2 usage >&2 exit 2 fi
WORKTREE="$(cd "$WORKTREE" && pwd)" mkdir -p "$LOG_DIR" LOG_FILE="$LOG_DIR/harness-$(date -u +%Y%m%dT%H%M%SZ)-$$.log" SEALED_LOG_FILE="${LOG_FILE%.log}.sealed.log" ATTESTATION_FILE="${LOG_FILE%.log}.attestation.json" EVENT_FILE="${LOG_FILE%.log}.events.tsv" # Волна 5.2: отдельный артефакт с КОНКРЕТНЫМИ именами тестов (cargo/pytest), # иначе в аттестации были лишь названия шагов (замечание Claude). TEST_NAMES_FILE="${LOG_FILE%.log}.tests.txt" touch "$EVENT_FILE" touch "$TEST_NAMES_FILE" exec > >(tee -a "$LOG_FILE") 2>&1
status() { local state="$1" label="$2" exit_code="${3:-0}" command="${4:-}" printf '%s %s\n' "$state" "$label" printf '%s\t%s\t%s\t%s\n' "$state" "$exit_code" "$label" "$command" >>"$EVENT_FILE" if [[ "$state" == FAIL ]]; then FAILURES=$((FAILURES + 1)) elif [[ "$state" == BLOCKED ]]; then BLOCKED_COUNT=$((BLOCKED_COUNT + 1)) if ((ALLOW_BLOCKED == 0)); then FAILURES=$((FAILURES + 1)) fi fi return 0 }
run_step() { local label="$1"; shift printf 'RUN %s\n' "$label" local command_text command_text="$(printf '%q ' "$@")" printf 'COMMAND %s\n' "$command_text" set +e "$@" local rc=$? set -e if ((rc == 0)); then status PASS "$label" "$rc" "$command_text" else status FAIL "$label (see log)" "$rc" "$command_text" fi return 0 }
run_worktree_step() { local label="$1"; shift printf 'RUN %s\n' "$label" local command_text command_text="(cd $(printf '%q' "$WORKTREE") && $(printf '%q ' "$@"))" printf 'COMMAND %s\n' "$command_text" local out_file rc out_file="$(mktemp)" set +e # tee: вывод остаётся виден в логе прогона И сохраняется для извлечения имён тестов. (cd "$WORKTREE" && "$@") 2>&1 | tee "$out_file" rc=${PIPESTATUS[0]} set -e # Волна 5.2: в артефакт аттестации добавляем КОНКРЕТНЫЕ имена тестов, а не # только название шага. Berём строки cargo (`test <name> ... ok/FAILED`) # и pytest (`<file>::<test>`, сводку). Пустые/служебные отфильтровываем. if [[ -n "$TEST_NAMES_FILE" ]]; then { printf '### %s\n' "$label" grep -E '^test .+ \.\.\. (ok|FAILED|ignored)$' "$out_file" \ | sed -E 's/^test //; s/ \.\.\. .*$//' || true # pytest с -rA печатает строки вида `PASSED path::test` / `FAILED path::test` # в короткой сводке. Забираем и полные идентификаторы `path::test`. grep -E '^(PASSED|FAILED|ERROR) .+::' "$out_file" || true grep -E '^(PASSED|FAILED|ERROR) ' "$out_file" || true } >>"$TEST_NAMES_FILE" fi rm -f "$out_file" if ((rc == 0)); then status PASS "$label" "$rc" "$command_text" else status FAIL "$label (see log)" "$rc" "$command_text" fi return 0 }
write_attestation() { local base_sha head_sha branch_name timestamp rustc cargo pg_version image_ref image_digest log_sha release_gate base_sha="$(git -C "$WORKTREE" rev-parse "$BASE" 2>/dev/null || printf 'UNRESOLVED')" head_sha="$(git -C "$WORKTREE" rev-parse "$BRANCH" 2>/dev/null || printf 'UNRESOLVED')" branch_name="$(git -C "$WORKTREE" symbolic-ref --short -q HEAD 2>/dev/null || printf '%s' "$BRANCH")" timestamp="$(date -u +%Y-%m-%dT%H:%M:%SZ)" rustc="$(rustc -Vv 2>/dev/null || printf 'UNAVAILABLE')" cargo="$(cargo -V 2>/dev/null || printf 'UNAVAILABLE')" pg_version="${PG_VERSION:-UNAVAILABLE}" image_ref="postgres:16-alpine" image_digest="$(docker image inspect --format '{{index .RepoDigests 0}}' "$image_ref" 2>/dev/null || printf 'UNAVAILABLE')" log_sha="$(sha256sum "$SEALED_LOG_FILE" | awk '{print $1}')" release_gate="$( ((ALLOW_BLOCKED == 1)) && printf 'CONDITIONAL' || printf 'STRICT' )" export ATTESTATION_FILE base_sha head_sha branch_name timestamp rustc cargo pg_version image_ref image_digest log_sha release_gate BLOCKED_COUNT FULL_WORKSPACE_TEST TEST_DB_HOST TEST_DB_PORT TEST_DB_NAME TEST_DB_USER SANITIZED_TEST_DATABASE_URL CREDENTIALS_REDACTED EVENT_FILE SEALED_LOG_FILE TEST_NAMES_FILE python3 - <<'PY' import json, os
def read_tests(path): """Список «шаг -> имена тестов» из TEST_NAMES_FILE (Волна 5.2).""" suites, cur = [], None try: with open(path, encoding="utf-8") as f: for line in f: line = line.rstrip("\n") if line.startswith("### "): cur = {"label": line[4:], "tests": []} suites.append(cur) elif cur is not None and line: cur["tests"].append(line) except FileNotFoundError: pass return suites
def sha256_of(path): """Хеш файла или None, если его нет.""" try: import hashlib h = hashlib.sha256() with open(path, "rb") as fh: for chunk in iter(lambda: fh.read(65536), b""): h.update(chunk) return h.hexdigest() except FileNotFoundError: return None
events = [] with open(os.environ["EVENT_FILE"], encoding="utf-8") as f: for line in f: state, code, label, command = line.rstrip("\n").split("\t", 3) events.append({"status": state, "exit_code": int(code), "label": label, "command": command}) test_suites = read_tests(os.environ.get("TEST_NAMES_FILE", "")) # Волна 5.3: честная статистика имён. Группы пересекаются (lib-юниты входят # в full-workspace-прогон), поэтому сумма строк > числа уникальных. Приводим оба, # чтобы «N тестов» нельзя было прочитать как «N разных покрытых случаев». _all = [t for s in test_suites for t in s["tests"]] _unique = sorted(set(_all)) test_counts = { "rows_total": len(_all), "unique_names": len(_unique), "duplicates": len(_all) - len(_unique), "note": "rows_total суммирует группы (возможны пересечения); unique_names — честное число разных имён", } artifacts = [{"path": os.environ["SEALED_LOG_FILE"], "sha256": os.environ["log_sha"]}] tests_path = os.environ.get("TEST_NAMES_FILE", "") if tests_path and sha256_of(tests_path): artifacts.append({"path": tests_path, "sha256": sha256_of(tests_path)}) with open(os.environ["ATTESTATION_FILE"], "w", encoding="utf-8") as f: json.dump({ "format": "swarm-dispatcher-acceptance-attestation/v1", "base_sha": os.environ["base_sha"], "branch": os.environ["branch_name"], "head_sha": os.environ["head_sha"], "timestamp_utc": os.environ["timestamp"], "release_gate": os.environ["release_gate"], "blocked_count": int(os.environ["BLOCKED_COUNT"]), "full_workspace_test_requested": bool(int(os.environ["FULL_WORKSPACE_TEST"])), "toolchain": {"rustc_Vv": os.environ["rustc"], "cargo": os.environ["cargo"]}, "postgres": {"server_version": os.environ["pg_version"], "image": os.environ["image_ref"], "image_digest": os.environ["image_digest"]}, "test_database": {"dsn": os.environ.get("SANITIZED_TEST_DATABASE_URL", "UNAVAILABLE"), "host": os.environ.get("TEST_DB_HOST", "UNAVAILABLE"), "port": os.environ.get("TEST_DB_PORT", "UNAVAILABLE"), "db": os.environ.get("TEST_DB_NAME", "UNAVAILABLE"), "user": os.environ.get("TEST_DB_USER", "UNAVAILABLE")}, "credentials_redacted": bool(int(os.environ["CREDENTIALS_REDACTED"])), "statuses": events, "test_names": test_suites, "test_counts": test_counts, "log": {"path": os.environ["SEALED_LOG_FILE"], "sha256": os.environ["log_sha"]}, "artifacts": artifacts, }, f, indent=2, sort_keys=True) f.write("\n") # Волна 5.3: печатаем честную статистику имён в стандартный вывод harness, # чтобы «N тестов» нельзя было прочитать по-разному. print("[test-names] rows_total=%d unique=%d duplicates=%d" % ( test_counts["rows_total"], test_counts["unique_names"], test_counts["duplicates"])) PY }
cleanup() { local rc=$? if [[ -n "$CONTAINER" ]] && command -v docker >/dev/null 2>&1; then docker rm -f "$CONTAINER" >/dev/null 2>&1 || true printf 'PASS disposable container cleaned: %s\n' "$CONTAINER" fi PG_VERSION="${PG_VERSION:-UNAVAILABLE}" if ((rc != 0 || FAILURES != 0)); then printf 'FAIL acceptance harness completed with %d failure(s); log: %s; attestation: %s\n' "$FAILURES" "$LOG_FILE" "$ATTESTATION_FILE" else printf 'PASS acceptance harness complete; log: %s; attestation: %s\n' "$LOG_FILE" "$ATTESTATION_FILE" fi # Remove the ephemeral credential before sealing generated artifacts. if [[ -n "$DB_PASSWORD" && -f "$LOG_FILE" ]]; then sed -i "s|$DB_PASSWORD|[REDACTED]|g" "$LOG_FILE" if grep -Fq "$DB_PASSWORD" "$LOG_FILE"; then printf 'FAIL temporary database password remains in log\n' FAILURES=$((FAILURES + 1)) else CREDENTIALS_REDACTED=1 printf 'PASS temporary database password absent from log\n' fi fi # Seal the complete sanitized log before generating JSON; attestation generation emits no log output. cp -- "$LOG_FILE" "$SEALED_LOG_FILE" write_attestation exit "$((rc != 0 ? rc : (FAILURES > 0 ? 1 : 0)))" } trap cleanup EXIT
check_diff_scope() { local path rule prefix matched if [[ -n "$ALLOWLIST_FILE" ]]; then [[ -f "$ALLOWLIST_FILE" ]] || { printf 'allowlist file not found: %s\n' "$ALLOWLIST_FILE"; return 1; } fi while IFS= read -r path; do [[ -z "$path" ]] && continue matched=0 if [[ -n "$ALLOWLIST_FILE" ]]; then while IFS= read -r rule || [[ -n "$rule" ]]; do rule="${rule%%#*}" rule="$(printf '%s' "$rule" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')" [[ -z "$rule" ]] && continue if [[ "$rule" == */\* ]]; then prefix="${rule%/*}/" [[ "$path" == "$prefix"* ]] && matched=1 else [[ "$path" == "$rule" ]] && matched=1 fi ((matched)) && break done < "$ALLOWLIST_FILE" else [[ "$path" == scripts/acceptance_harness.sh || "$path" == docs/audit/* ]] && matched=1 fi ((matched)) || { printf 'out-of-scope path: %s\n' "$path"; return 1; } done < <(git -C "$WORKTREE" diff --name-only "$BASE..$BRANCH") }
shell_checks() { local file bash -n "$SCRIPT_DIR/acceptance_harness.sh" while IFS= read -r file; do bash -n "$file" done < <(find "$WORKTREE/scripts" -maxdepth 1 -type f -name '*.sh' -print) if command -v shellcheck >/dev/null 2>&1; then shellcheck "$SCRIPT_DIR/acceptance_harness.sh" else status BLOCKED "shellcheck unavailable (bash -n passed)" fi }
# FIND-01 (Волна 5.2, переработан): после снятия feature-гейта модули shell-tools # компилируются ВСЕГДА, и символы модуля физически живут в бинаре (мангалинг: # `swarm_worker7sandbox`, а не `swarm_worker::sandbox`). Поэтому старая # негативная проверка по `::`-форме была ВАКУУМНОЙ (grep 0 совпадений всегда, # даже при утечке) — Claude верно поймал это. # # Новая цель шага: доказать, что единственная защита вместо compile-гейта — # runtime-гейт `WORKER_SHELL_TOOLS` — РЕАЛЬНО вкомпилирована в бинарь. # Положительный контроль: строка отказа гейта обязана присутствовать. # Плюс негативный контроль в корректной форме: символы `agent_loop`/`allowlist` # НЕ должны попадать в бинарь (эти модули не используются воркером по умолчанию). shell_tools_ban() { local bin="$WORKTREE/target/release/swarm-worker" if ! (cd "$WORKTREE" && cargo build --release -p swarm-worker --bin swarm-worker --locked >/dev/null 2>&1); then status FAIL "FIND-01: cargo build swarm-worker (no shell-tools) failed" 1 "cargo build --release -p swarm-worker --bin swarm-worker" return 0 fi if [ ! -f "$bin" ]; then status FAIL "FIND-01: swarm-worker binary missing after build" 1 "ls $bin" return 0 fi
# 1) ПОЛОЖИТЕЛЬНЫЙ КОНТРОЛЬ (главный): runtime-гейт вкомпилирован. # Именно эта строка — актуальная защита вместо compile-гейта. # # ВАЖНО (Волна 5.2): НЕ используем `strings | grep -q` — при `set -o pipefail` # `grep -q` выходит на первом совпадении, `strings` получает SIGPIPE, и пайп # возвращает ненулевой код даже при успешном grep (ложный FAIL). Сначала # сбрасываем вывод strings в переменную, потом грепаем ПО ПЕРЕМЕННОЙ. local gate_string='shell-tools disabled (set WORKER_SHELL_TOOLS=1 to enable)' local bin_strings bin_strings="$(strings "$bin")" if ! grep -qF "$gate_string" <<<"$bin_strings"; then status FAIL "FIND-01: runtime-gate string absent in binary (gate NOT compiled in)" 1 \ "strings swarm-worker | grep -F '$gate_string'" return 0 fi
# 2) НЕГАТИВНЫЙ КОНТРОЛЬ в КОРРЕКТНОЙ форме мангалинга. # `agent_loop`/`allowlist` не должны линковаться в бинарь воркера: воркер # не запускает agent loop по умолчанию. Проверяем legacy-форму, которую # реально порождает rustc (а не `::`, где grep всегда давал 0). local hit=0 sym for sym in swarm_worker9agent_loop swarm_worker9allowlist agent_system_prompt run_shell WORKER_ALLOWED_COMMANDS; do if grep -q "$sym" <<<"$bin_strings"; then hit=1 printf 'FIND-01 BAN VIOLATION: %s found in swarm-worker binary\n' "$sym" fi done if ((hit != 0)); then status FAIL "FIND-01: shell-tools leaked into swarm-worker binary" 1 "strings swarm-worker | grep -E '<banned-legacy>|gate-string'" return 0 fi
status PASS "FIND-01: runtime-gate present + shell-tools modules absent" 0 "strings swarm-worker | grep -F '$gate_string'" }
# Волна 5.2 (fail-closed): гарантия, что интеграция реально исполняется. # # Инцидент (найден ночным прогоном): harness-шаг --full-workspace-test # собирал `cargo test --workspace` без `--ignored`, поэтому 21 интеграционный # тест молча игнорировался, а гейт оставался зелёным. Чтобы это не повторилось, # явно проверяем: в файле имён тестов есть имена интеграционных тестов из # worker_sandbox (sandbox_*/agent_loop_*), и их не меньше ожидаемого минимума. check_integration_not_ignored() { local min_expected=8 n n="$(grep -cE '^(sandbox|agent_loop)_' "$TEST_NAMES_FILE" 2>/dev/null || true)" n="${n:-0}" if ((n < min_expected)); then status FAIL "integration tests executed only ${n} (min ${min_expected}); --ignored may be silently skipping" 1 \ "grep -cE '^(sandbox|agent_loop)_' ${TEST_NAMES_FILE}" return 0 fi status PASS "integration tests executed: ${n} (>= ${min_expected})" 0 \ "grep -cE '^(sandbox|agent_loop)_' ${TEST_NAMES_FILE}" }
# Волна 5.2: backup/restore арбитр (KNOWN_LIMITATIONS 5.1). # Дамп disposable-БД восстанавливается в новую БД и проходит verify_chain. backup_restore_check() { [[ "$DB_READY" == 1 ]] || { status FAIL "backup/restore requires provisioned DB" 1 ""; return 0; } local tmp tmp="$(mktemp -d)" # DATABASE_URL для ops/db_backup.sh (postgres://-форма). local url="postgres://postgres:${DB_PASSWORD}@127.0.0.1:${TEST_DB_PORT}/${TEST_DB_NAME}" if ! (cd "$WORKTREE" && DATABASE_URL="$url" ./ops/db_backup.sh dump "$tmp") >/dev/null 2>&1; then status FAIL "backup/restore: dump failed" 1 "ops/db_backup.sh dump" rm -rf "$tmp"; return 0 fi local dump="" f for f in "$tmp"/*.dump; do [[ -e "$f" ]] && dump="$f" done if [[ -z "$dump" ]]; then status FAIL "backup/restore: no dump produced" 1 "ops/db_backup.sh dump" rm -rf "$tmp"; return 0 fi if (cd "$WORKTREE" && DATABASE_URL="$url" ./ops/db_backup.sh verify "$dump") >/dev/null 2>&1; then status PASS "backup/restore round-trip verified" 0 "ops/db_backup.sh verify" else status FAIL "backup/restore: verify failed" 1 "ops/db_backup.sh verify" fi rm -rf "$tmp" }
compose_check() { local env_file rendered env_file="$(mktemp)" cat >"$env_file" <<'ENV' DB_PASSWORD=dummy_db_password SWARM_PW_WORKER=dummy_worker_password SWARM_PW_WATCHDOG=dummy_watchdog_password SWARM_PW_PLANNER=dummy_planner_password SWARM_PW_REVIEWER=dummy_reviewer_password SWARM_PW_OPERATOR=dummy_operator_password SWARM_PW_CLI=dummy_cli_password SWARM_PW_W1=dummy_w1_password SWARM_PW_W2=dummy_w2_password SWARM_PW_W_1=dummy_w_1_password SWARM_PW_GPU_1=dummy_gpu_1_password WORKER_LLM_API_KEY=dummy_llm_api_key ENV rendered="$(mktemp)" docker compose --env-file "$env_file" -f "$WORKTREE/docker-compose.yml" config >"$rendered" 2>/dev/null || true rm -f "$env_file" [[ -s "$rendered" ]] || { rm -f "$rendered"; return 1; } RENDERED_COMPOSE_FILE="$rendered" compose_security_acceptance local rc=$? rm -f "$rendered" return $rc }
# P0-3: pin the worker container boundary in a verifiable check, not just docs. compose_security_acceptance() { python3 - <<'PY' import os, sys, yaml with open(os.environ["RENDERED_COMPOSE_FILE"], encoding="utf-8") as f: cfg = yaml.safe_load(f) or {} services = cfg.get("services", {}) workers = [n for n in services if n.startswith("worker-")] def fail(msg): print(f"FAIL {msg}") sys.exit(1) if not workers: fail("no worker-* service in compose") for name in sorted(workers): svc = services[name] if svc.get("read_only") is not True: fail(f"{name}: read_only must be true") if "ALL" not in (svc.get("cap_drop") or []): fail(f"{name}: cap_drop must include ALL") sec = svc.get("security_opt") or [] if not any("no-new-privileges" in s for s in sec): fail(f"{name}: no-new-privileges missing") for vol in svc.get("volumes") or []: src = vol if isinstance(vol, str) else (vol.get("source") or "") if "docker.sock" in str(src): fail(f"{name}: docker.sock must not be mounted by default") if svc.get("privileged") is True: fail(f"{name}: privileged must not be set") if svc.get("network_mode") == "host": fail(f"{name}: host network mode not allowed") print("PASS worker container boundary pinned: " + ", ".join(sorted(workers)))
# Issue #24: DSN каждого сервиса обязан соответствовать его БД-роли. # Иначе сервис стартует, но падает на правах (watchdog под swarm_worker_w1 # не имеет reclaim_expired/promote_ready -> цикл задач стоит). def get_env(svc, key): env = svc.get("environment") if isinstance(env, dict): return env.get(key) for e in env or []: if str(e).startswith(key + "="): return str(e)[len(key) + 1:] return None
def service_db_role(name, svc): if name == "watchdog": return "swarm_watchdog" if name == "reviewer": return "swarm_reviewer" if name == "cli": return "swarm_cli" if name == "planner": return "swarm_planner" if name.startswith("worker-"): # Роль = swarm_worker_<normalize(WORKER_ID)>; см. roles_2b.sql. # normalize: lowercase + дефис -> подчёркивание ('w-1' -> 'w_1'). wid = get_env(svc, "WORKER_ID") if not wid: fail(f"{name}: WORKER_ID missing (cannot derive DB role)") return "swarm_worker_" + str(wid).lower().replace("-", "_") return None
role_checked = [] for name in sorted(services): expected = service_db_role(name, services[name]) if expected is None: continue dsn = get_env(services[name], "DATABASE_URL") if not dsn: fail(f"{name}: DATABASE_URL missing (expected role {expected})") # postgres://<user>:<pw>@host:port/db try: userinfo = dsn.split("://", 1)[1].split("@", 1)[0] user = userinfo.split(":", 1)[0] except IndexError: fail(f"{name}: malformed DATABASE_URL") if user != expected: fail(f"{name}: DATABASE_URL role is '{user}', expected '{expected}'") role_checked.append(f"{name}={user}") if role_checked: print("PASS service DSN matches DB role: " + ", ".join(role_checked)) PY }
pg() { local user="$1" password="$2"; shift 2 docker exec -e PGPASSWORD="$password" "$CONTAINER" psql -X -v ON_ERROR_STOP=1 -U "$user" -d c2_swarm "$@" }
expect_failure() { local label="$1"; shift if "$@" >/dev/null 2>&1; then status FAIL "$label unexpectedly succeeded" return 1 fi status PASS "$label" }
provision_database() { local failures_before=$FAILURES command -v docker >/dev/null 2>&1 DB_PASSWORD="c2_$(openssl rand -hex 20)" CONTAINER="c2_acceptance_${USER:-user}_$$" CONTAINER="${CONTAINER//[^a-zA-Z0-9_.-]/_}" local common_args=( --name "$CONTAINER" -e POSTGRES_DB=c2_swarm -e POSTGRES_USER=postgres -e "POSTGRES_PASSWORD=$DB_PASSWORD" -p 127.0.0.1::5432 -v "$WORKTREE/schema/schema_v0.sql:/c2/schema.sql:ro" -v "$WORKTREE/step2/roles.sql:/c2/roles.sql:ro" -v "$WORKTREE/step2b/roles_2b.sql:/c2/roles_2b.sql:ro" -v "$WORKTREE/step2/roles_patch_planner_status.sql:/c2/patch_planner.sql:ro" -v "$WORKTREE/step2/roles_patch_tool_call_audit.sql:/c2/patch_tool_call.sql:ro" -v "$WORKTREE/schema/migrations:/c2/migrations:ro" ) docker run -d "${common_args[@]}" postgres:16-alpine >/dev/null PG_VERSION="$(docker exec "$CONTAINER" postgres --version)" TEST_DB_PORT="$(docker port "$CONTAINER" 5432/tcp | awk -F: 'NR == 1 {print $NF}')" [[ "$TEST_DB_PORT" =~ ^[0-9]+$ ]] TEST_DATABASE_URL="host=localhost port=${TEST_DB_PORT} user=postgres password=${DB_PASSWORD} dbname=${TEST_DB_NAME}" SANITIZED_TEST_DATABASE_URL="host=localhost port=${TEST_DB_PORT} user=postgres password=[REDACTED] dbname=${TEST_DB_NAME}" [[ "$TEST_DATABASE_URL" == *"password=${DB_PASSWORD}"* ]] [[ "$SANITIZED_TEST_DATABASE_URL" != *"${DB_PASSWORD}"* ]] local ready=0 for _ in {1..60}; do if docker exec -e PGPASSWORD="$DB_PASSWORD" "$CONTAINER" \ psql -X -U postgres -d c2_swarm -c 'select 1' >/dev/null 2>&1; then ready=1 break fi sleep 1 done ((ready == 1))
# Apply exactly the repository's accepted order, with ON_ERROR_STOP on each file. pg postgres "$DB_PASSWORD" -f /c2/schema.sql pg postgres "$DB_PASSWORD" -v worker_pw=c2_worker -v watchdog_pw=c2_watchdog \ -v planner_pw=c2_planner -v reviewer_pw=c2_reviewer -v operator_pw=c2_operator \ -v cli_pw=c2_cli -f /c2/roles.sql pg postgres "$DB_PASSWORD" -v w1_pw=c2_w1 -v w2_pw=c2_w2 -v w_1_pw=c2_w_1 \ -v gpu_1_pw=c2_gpu_1 -f /c2/roles_2b.sql pg postgres "$DB_PASSWORD" -f /c2/patch_planner.sql pg postgres "$DB_PASSWORD" -f /c2/patch_tool_call.sql # Миграции применяются тем же порядком, что и в продакшн-цепочке # (scripts/05-migrations.sh): лексикографически по имени файла. Без них в # тест-БД отсутствует llm_calls, и воркер с cost ledger (Issue #2/#3) не # проходит даже базовый сценарий — ложная регрессия в harness, а не в коде. local mig for mig in "$WORKTREE"/schema/migrations/*.sql; do [ -e "$mig" ] || continue pg postgres "$DB_PASSWORD" -f "/c2/migrations/$(basename "$mig")" || return 1 done DB_READY=1 status PASS "disposable PostgreSQL 16 provisioned and initialized" }
database_acceptance() { local failures_before=$FAILURES [[ "$DB_READY" == 1 ]]
local common_worker_login worker_login common_worker_login="$(pg postgres "$DB_PASSWORD" -Atc "select rolcanlogin from pg_roles where rolname='swarm_worker'")" worker_login="$(pg postgres "$DB_PASSWORD" -Atc "select rolcanlogin from pg_roles where rolname='swarm_worker_w1'")" if [[ "$common_worker_login" == f ]]; then status PASS "common swarm_worker is NOLOGIN" else status FAIL "common swarm_worker must be NOLOGIN (P0 RBAC fix is absent from this branch)" fi if [[ "$worker_login" == t ]]; then status PASS "per-worker role swarm_worker_w1 is LOGIN" else status FAIL "per-worker role swarm_worker_w1 must be LOGIN" fi
pg swarm_worker_w1 c2_w1 -c "select register_worker('w1', '{\"ram_gb\":16}'::jsonb)" status PASS "per-worker register_worker works" expect_failure "worker identity spoofing is rejected" pg swarm_worker_w1 c2_w1 -c "select register_worker('w2', '{\"ram_gb\":16}'::jsonb)" expect_failure "cli claim_task is denied" pg swarm_cli c2_cli -c "select claim_task('w1', 10)" expect_failure "SET ROLE spoofing is denied" pg swarm_worker_w1 c2_w1 -c "set role swarm_worker_w2" ((FAILURES == failures_before)) }
review_gate_acceptance() { local failures_before=$FAILURES [[ "$DB_READY" == 1 ]] local suite local suites=( "step2/test_roles.py|RBAC role separation + catalog invariants (P0 #3/#4)" "step2b/test_roles_2b.py|worker identity, SET ROLE, id collisions (P0 #4)" "step2/test_review_gate.py|review-gate negative tests (P0 #5)" "tests/test_v0.py|state machine: lease/epoch, add_dep, reopen cascade (P0 #6/#7)" "tests/test_cost_reconciliation.py|cost ledger reconciliation vs relay.fast (Issue #2)" "tests/test_f8_orphan_llm_spend.py|F8 budget protects real spend, not only complete (Issue 5.10)" # FIND-NEW-04: три сьюта лежали мёртвым грузом мимо harness и CI. # test_f8 уже выше; ниже — остальные два (юнит-части, без сети/БД). "tests/test_model_quality.py|model quality view -> selector stats (Issue #7/#10)" "tests/test_model_catalog.py|relay.fast pricing -> USD/1M recalculation (Issue #7/#10)" ) for suite in "${suites[@]}"; do [[ -f "$WORKTREE/${suite%%|*}" ]] || { status BLOCKED "missing test suite: ${suite%%|*}"; return 0; } done local py="$WORKTREE/.venv/bin/python" if [[ ! -x "$py" ]]; then if command -v uv >/dev/null 2>&1; then (cd "$WORKTREE" && uv venv --quiet .venv && uv pip install --quiet --python .venv/bin/python pytest psycopg2-binary) || true fi fi if [[ ! -x "$py" ]]; then status BLOCKED "python venv with pytest+psycopg2 unavailable (install uv or .venv)" return 0 fi export ROLES_DB=c2_swarm ROLES_HOST=127.0.0.1 ROLES_PORT=$TEST_DB_PORT ADMIN_PW="$DB_PASSWORD" export SWARM_PW_W1=c2_w1 SWARM_PW_W2=c2_w2 SWARM_PW_W_1=c2_w_1 SWARM_PW_GPU_1=c2_gpu_1 export SWARM_PW_WORKER=c2_worker SWARM_PW_WATCHDOG=c2_watchdog SWARM_PW_PLANNER=c2_planner export SWARM_PW_REVIEWER=c2_reviewer SWARM_PW_OPERATOR=c2_operator SWARM_PW_CLI=c2_cli # tests/test_v0.py speaks PGDSN (superuser): reuse the disposable DSN. export PGDSN="dbname=c2_swarm user=postgres host=127.0.0.1 port=$TEST_DB_PORT password=$DB_PASSWORD" # Волна 5.2: арбитры волны 4 (F15/F4/FIND-04/F2) требуют W4_*-окружения. # Без него conftest их блокировал (BLOCKED), и 38 тестов НИКОГДА не # исполнялись ни harness, ни ручным прогоном (найдено ночной сессией). export W4_ADMIN_DSN="host=127.0.0.1 port=$TEST_DB_PORT user=postgres password=$DB_PASSWORD dbname=c2_swarm" export W4_W1_PW=c2_w1 W4_W2_PW=c2_w2 for suite in "${suites[@]}"; do run_worktree_step "${suite##*|} on patched c2_ database" \ "$py" -m pytest -q -rA "${suite%%|*}" done # Волна 5.2: волна-4 арбитры — отдельным шагом с W4_*-окружением. if [[ -f "$WORKTREE/tests/test_contract_form_f15.py" ]]; then run_worktree_step "wave-4 PG arbiters (F15/F4/FIND-04/F2) on patched c2_ database" \ "$py" -m pytest -q -rA \ tests/test_contract_form_f15.py tests/test_fail_unblock_f4.py \ tests/test_find04_record_tool_call_identity.py tests/test_worker_identity_f3.py \ tests/test_review_gate_f2.py tests/test_review_gate_wave4.py fi unset ROLES_DB ROLES_HOST ROLES_PORT ADMIN_PW PGDSN W4_ADMIN_DSN W4_W1_PW W4_W2_PW unset SWARM_PW_W1 SWARM_PW_W2 SWARM_PW_W_1 SWARM_PW_GPU_1 SWARM_PW_WORKER SWARM_PW_WATCHDOG unset SWARM_PW_PLANNER SWARM_PW_REVIEWER SWARM_PW_OPERATOR SWARM_PW_CLI ((FAILURES == failures_before)) }
run_step "diff allowlist ($BASE..$BRANCH)" check_diff_scope run_step "git diff --check" git -C "$WORKTREE" diff --check "$BASE..$BRANCH" run_step "shell syntax checks" shell_checks # Техдолг (2026-10-14): drift guard против расхождения тел функций между # schema/schema_v0.sql и step2b/roles_2b.sql. roles_2b.sql перекрывает пять # функций воркера (добавляя identity-проверку); если кто-то поправит тело в # одном файле и забудет в другом — тест краснеет. Класс дефекта уже дважды # кусал: submit_review (F16г) и complete_task (Issue #20). # Тест не требует БД. Окружение готовим ТЕМ ЖЕ venv, что и python-арбитры: # pytest + psycopg2-binary обязаны стоять вместе в .venv, иначе предыдущий # шаг «rbac/python suites» создал бы .venv с одним pytest и без psycopg2 → # все DB-арбитры падают на ImportError (регрессия PR #39, доказана в CI # run 38439933042). Единый провижн устраняет расхождение. _dg_py="$WORKTREE/.venv/bin/python" if [[ ! -x "$_dg_py" ]]; then if command -v uv >/dev/null 2>&1; then (cd "$WORKTREE" && uv venv --quiet .venv \ && uv pip install --quiet --python .venv/bin/python pytest psycopg2-binary) || true fi fi if [[ -x "$_dg_py" ]]; then run_worktree_step "duplicate function-body drift guard (schema_v0 vs roles_2b)" \ .venv/bin/python -m pytest -q tests/test_no_duplicate_function_bodies.py else status BLOCKED "drift guard blocked: .venv with pytest+psycopg2 unavailable" fi # Issue #1: архитектурные проверки ast-grep. `test` проверяет сами правила по # фикстурам (падение → exit 4), `scan --error` — код репозитория (находка → exit 1). # Fail-closed: без инструмента гейт не «зелёный», а BLOCKED (как cargo/docker). if command -v ast-grep >/dev/null 2>&1; then run_worktree_step "ast-grep rule fixtures (Issue #1)" ast-grep test --skip-snapshot-tests run_worktree_step "ast-grep architecture scan (Issue #1)" ast-grep scan --error else status BLOCKED "ast-grep unavailable: architecture checks not run" fi if command -v docker >/dev/null 2>&1; then run_step "compose config with dummy environment" compose_check # Арбитр ролей: self-test проверяет, что арбитр КРАСНЕЕТ на подмене роли # (класс #24: watchdog под воркерской ролью). Чистые функции, стека не # требует → безопасно в CI. Живой прогон (по контейнерам) — операционная # проверка: scripts/compose_roles_arbiter.sh (см. docs/AGENTS.md). run_step "compose roles arbiter self-test (#24)" "$WORKTREE/scripts/compose_roles_arbiter.sh" --self-test run_step "provision disposable PostgreSQL 16 before Rust tests" provision_database else status BLOCKED "docker unavailable: compose config and database acceptance not run" fi if command -v cargo >/dev/null 2>&1; then run_worktree_step "Rust library/unit tests" cargo test --workspace --lib --locked -- --test-threads=1 run_step "FIND-01 shell-tools symbol ban (worker binary)" shell_tools_ban else status BLOCKED "cargo unavailable: Rust unit tests not run" fi if ((FULL_WORKSPACE_TEST)); then if ((DB_READY == 1)); then export TEST_DATABASE_URL export DATABASE_URL="$TEST_DATABASE_URL" # Волна 5.2: два шага вместо одного — релизный гейт должен реально ВИДЕТЬ # интеграцию. Раньше `cargo test --workspace` без `--ignored` молча # игнорировал 21 интеграционный тест (все Docker/PG-тесты), т.е. # --full-workspace-test завышал уверенность (найдено ночным прогоном). # FIND-01: shell-tools тесты требуют feature; бинарь без неё собирается в shell_tools_ban. run_worktree_step "required full workspace test with disposable c2_ database" \ cargo test --workspace --features swarm-worker/shell-tools --locked -- --test-threads=1 # Интеграция: `--ignored` при поднятой БД (требует TEST_DATABASE_URL). # Тесты сами падают (FIND-08), если DSN не задан — не молчаливый skip. run_worktree_step "required integration tests (--ignored) on disposable c2_ database" \ cargo test --workspace --features swarm-worker/shell-tools --locked -- --test-threads=1 --ignored # Волна 5.2 (fail-closed): убедиться, что шаг --ignored ФАКТИЧЕСКИ выполнил # интеграционные тесты, а не молча их пропустил. Защита от возврата дефекта: # предыдущий инцидент — 21 тест игнорировался, а гейт был "зелёным". check_integration_not_ignored # Волна 5.2: backup/restore арбитр (охват KNOWN_LIMITATIONS 5.1). Дамп # disposable-БД восстанавливается в новую БД + verify_chain по задачам. run_step "backup/restore round-trip (ops/db_backup.sh verify)" backup_restore_check else status BLOCKED "full workspace test blocked: disposable c2_ database is not ready" fi else status BLOCKED "full workspace test not requested (use --full-workspace-test for release gate)" fi if command -v docker >/dev/null 2>&1; then run_step "RBAC smoke on disposable c2_ database" database_acceptance run_step "RBAC/path/review Python suites on disposable c2_ database" review_gate_acceptance fi

#!/usr/bin/env python3 """Собирает XML-бандл всех скриптов репозитория для аудита.
Только чтение. Секреты (.env) НЕ включаются — только .env.example. Выход: docs/audit/SCRIPTS_BUNDLE_v0.4.xml """ from __future__ import annotations
import hashlib import os import subprocess import sys from datetime import datetime, timezone from pathlib import Path from xml.sax.saxutils import escape, quoteattr
REPO = Path(__file__).resolve().parent.parent OUT_DIR = REPO / "docs" / "audit" OUT_XML = OUT_DIR / "SCRIPTS_BUNDLE_v0.4.xml"
# (путь, роль, язык) FILES = [ # --- скрипты инициализации --- ("scripts/02-roles.sh", "init", "bash"), ("scripts/03-roles-2b.sh", "init", "bash"), ("scripts/03-role-patches.sh", "init", "bash"), # --- схема и роли (SQL) --- ("schema/schema_v0.sql", "schema", "sql"), ("step2/roles.sql", "roles", "sql"), ("step2/roles_patch_planner_status.sql", "roles-patch", "sql"), ("step2/roles_patch_tool_call_audit.sql", "roles-patch", "sql"), ("step2b/roles_2b.sql", "roles", "sql"), ("docs/history/obsolete/roles_2b_patch_section3.sql", "roles-patch-obsolete", "sql"), # --- контейнеризация --- ("Dockerfile", "container", "dockerfile"), ("sandbox/Dockerfile", "container", "dockerfile"), ("docker-compose.yml", "container", "yaml"), # --- тесты --- ("tests/test_v0.py", "test", "python"), ("step2/test_roles.py", "test", "python"), ("step2b/test_roles_2b.py", "test", "python"), # --- конфиг без секретов --- (".env.example", "config", "dotenv"), # --- вспомогательное --- ("rust_fixes/dispatcher.rs", "patch", "rust"), ]
FORBIDDEN = {".env", ".env.bak.1791466553"}
def sha256(path: Path) -> str: h = hashlib.sha256() with path.open("rb") as fh: for chunk in iter(lambda: fh.read(65536), b""): h.update(chunk) return h.hexdigest()
def md5(path: Path) -> str: h = hashlib.md5() with path.open("rb") as fh: for chunk in iter(lambda: fh.read(65536), b""): h.update(chunk) return h.hexdigest()
def git_info() -> dict: def run(*args): try: return subprocess.run( ["git", *args], cwd=REPO, capture_output=True, text=True, timeout=10 ) except Exception: return None
r = run("rev-parse", "HEAD") if r is None or r.returncode != 0: return {"is_git": "false", "note": "not a git repository"} return { "is_git": "true", "head": r.stdout.strip(), "branch": (run("rev-parse", "--abbrev-ref", "HEAD") or type("x", (), {"stdout": ""})).stdout.strip(), "dirty": "true" if (run("status", "--porcelain") and run("status", "--porcelain").stdout.strip()) else "false", }
def main() -> int: OUT_DIR.mkdir(parents=True, exist_ok=True) now = datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")
entries = [] missing = [] for rel, role, lang in FILES: p = REPO / rel if rel in FORBIDDEN or not p.is_file(): missing.append(rel) continue raw = p.read_bytes() try: text = raw.decode("utf-8") except UnicodeDecodeError: text = raw.decode("utf-8", errors="replace") entries.append( { "path": rel, "role": role, "lang": lang, "bytes": len(raw), "lines": text.count("\n") + (0 if text.endswith("\n") else 1), "sha256": sha256(p), "md5": md5(p), "text": text, } )
total_bytes = sum(e["bytes"] for e in entries) gi = git_info()
out = [] out.append('<?xml version="1.0" encoding="UTF-8"?>') out.append( '<audit-bundle schema="swarm-dispatcher.audit-bundle.v1" ' f'generated={quoteattr(now)} generator={quoteattr("scripts/build_audit_bundle.py")}>' ) out.append(" <project>") out.append(f" <name>swarm-dispatcher</name>") out.append(f" <root>{escape(str(REPO))}</root>") out.append(f" <git is_git={quoteattr(gi['is_git'])}" + (f" head={quoteattr(gi.get('head',''))} branch={quoteattr(gi.get('branch',''))} dirty={quoteattr(gi.get('dirty',''))}/>" if gi["is_git"] == "true" else "") + ("" if gi["is_git"] == "true" else f"><note>{escape(gi.get('note',''))}</note></git>")) out.append(" </project>") out.append(" <manifest>") out.append(f" <files count=\"{len(entries)}\" total_bytes=\"{total_bytes}\"/>") out.append(" <excluded>") out.append(" <file path=\".env\" reason=\"secrets\"/>") out.append(" <file path=\".env.bak.*\" reason=\"secrets\"/>") out.append(" <dir path=\"target/\" reason=\"build artifacts\"/>") out.append(" <dir path=\".venv/\" reason=\"virtualenv\"/>") out.append(" </excluded>") out.append(" <index>") for e in entries: out.append( f' <entry path={quoteattr(e["path"])} role={quoteattr(e["role"])} ' f'lang={quoteattr(e["lang"])} bytes="{e["bytes"]}" lines="{e["lines"]}" ' f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}/>' ) out.append(" </index>") out.append(" </manifest>") out.append(" <files>") for e in entries: out.append( f' <file path={quoteattr(e["path"])} role={quoteattr(e["role"])} ' f'lang={quoteattr(e["lang"])} bytes="{e["bytes"]}" lines="{e["lines"]}" ' f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}>' ) # CDATA, кроме случая когда текст содержит ]]> # Trailing blanks are stripped: embedded REPORT_*.md carry markdown # hard-breaks (two trailing spaces) which would otherwise land in the # bundle and trip `git diff --check` on any regenerated artifact. body = "\n".join(line.rstrip() for line in e["text"].rstrip("\n").split("\n")) if "]]>" in body: out.append(" <content encoding=\"xml-escaped\">") out.append(escape(body)) out.append(" </content>") else: out.append(" <content><![CDATA[") out.append(body) out.append("]]></content>") out.append(" </file>") out.append(" </files>") out.append("</audit-bundle>")
OUT_XML.write_text("\n".join(out) + "\n", encoding="utf-8") print(f"OK {OUT_XML}") print(f" files={len(entries)} total_bytes={total_bytes}") print(f" md5={md5(OUT_XML)} sha256={sha256(OUT_XML)}") if missing: print(f" MISSING: {', '.join(missing)}", file=sys.stderr) return 0
if __name__ == "__main__": raise SystemExit(main())

#!/usr/bin/env python3 """Собирает полный аудит-бандл проекта (весь код) в XML, по томам.
Тома: code — Rust-исходники, тесты, Cargo-манифесты, фикстуры infra — схема/роли SQL, init-скрипты, Dockerfile/compose, конфиги без секретов docs — документация проекта (docs/**, кроме писем inbound) + корневые отчёты
Только чтение. Секреты (.env*) и бинарники (.docx/.png) исключены. Выход: docs/audit/PROJECT_<VOLUME>_BUNDLE_v0.4.xml """ from __future__ import annotations
import hashlib import subprocess import sys from datetime import datetime, timezone from pathlib import Path from xml.sax.saxutils import escape, quoteattr
REPO = Path(__file__).resolve().parent.parent OUT_DIR = REPO / "docs" / "audit"
EXCL_DIRS = {"target", ".venv", "__pycache__", ".git", "node_modules", ".pytest_cache", ".mypy_cache"} EXCL_FILES = {".env", ".env.bak.1791466553"} BINARY_SUFFIX = {".docx", ".png", ".jpg", ".jpeg", ".gif", ".pdf", ".zip", ".gz", ".tar", ".rlib", ".rmeta", ".o", ".so"}
# volume -> (описание, [пути-файлы] или корневые префиксы для рекурсии) VOLUMES: dict[str, dict] = { "CODE": { "title": "Код проекта (Rust + тесты + манифесты)", "globs": ["crates/**/*.rs", "crates/**/Cargo.toml", "Cargo.toml", "Cargo.lock", "crates/**/*.json"], }, "INFRA": { "title": "Инфраструктура (SQL, init-скрипты, контейнеры, конфиг)", # FIND-NEW-05: `schema/*` НЕ рекурсивен — Path.glob('schema/*') # возвращает только `schema/migrations` (каталог), а `p.is_file()` # его отбрасывает. В итоге все 11 миграций (в т.ч. фикс F8 — # 011_budget_sync_and_root_cap.sql) выпадали из аудит-тома. # `schema/**/*.sql` рекурсивно берёт и schema_v0.sql, и migrations/*. "globs": ["schema/*", "schema/**/*.sql", "step2/*", "step2b/*", "scripts/*", "docker-compose.yml", "Dockerfile", ".env.example", ".dockerignore", ".gitignore", "LICENSE", "tests/*.py", ".github/workflows/*"], }, "DOCS": { "title": "Документация и отчёты (без писем history/inbound)", "globs": ["docs/**/*.md", "*.md", "docs/history/*.md"], "exclude_prefix": ["docs/history/inbound/", "docs/audit/"], }, "DOCS_CORE": { "title": "Ключевая документация (ТЗ, архитектура, ограничения, отчёты)", "globs": ["docs/TZ_*.md", "docs/ARCHITECTURE.md", "docs/KNOWN_LIMITATIONS.md", "docs/PROJECT_STATE.md", "docs/METHODOLOGY.md", "docs/VERIFICATION_LOG.md", "README.md", "CHANGELOG.md", "RESUME.md", "MANIFEST.md", "REPORT_*.md", "docs/audit/AUDITOR_BRIEF_v0.4.md", "docs/audit/AUDITOR_BRIEF_v0.4.en.md", "docs/audit/README_AUDIT_PACKAGE.md"], }, }
def sha256(b: bytes) -> str: return hashlib.sha256(b).hexdigest()
def md5(b: bytes) -> str: return hashlib.md5(b).hexdigest()
def file_digest(p: Path, algo: str) -> str: h = hashlib.new(algo) with p.open("rb") as fh: for chunk in iter(lambda: fh.read(65536), b""): h.update(chunk) return h.hexdigest()
def git_info() -> dict: try: r = subprocess.run(["git", "rev-parse", "HEAD"], cwd=REPO, capture_output=True, text=True, timeout=10) if r.returncode == 0: return {"is_git": "true", "head": r.stdout.strip()} except Exception: pass return {"is_git": "false", "note": "not a git repository"}
def collect(vol: dict) -> list[Path]: seen: set[Path] = set() ex_pfx = vol.get("exclude_prefix", []) for g in vol["globs"]: for p in sorted(REPO.glob(g)): if not p.is_file(): continue if set(p.relative_to(REPO).parts) & EXCL_DIRS: continue if p.name in EXCL_FILES or p.suffix in BINARY_SUFFIX: continue rel = p.relative_to(REPO).as_posix() if any(rel.startswith(x) for x in ex_pfx): continue seen.add(p) return sorted(seen, key=lambda p: p.relative_to(REPO).as_posix())
def lang_of(p: Path) -> str: n = p.name if n == "Dockerfile": return "dockerfile" if n == "Cargo.toml" or n == "Cargo.lock": return "toml" if n.startswith(".env"): return "dotenv" return {".rs": "rust", ".sql": "sql", ".sh": "bash", ".py": "python", ".md": "markdown", ".yml": "yaml", ".yaml": "yaml", ".json": "json", ".toml": "toml"}.get(p.suffix, "text")
def build_volume(name: str, vol: dict) -> tuple[Path, int, int]: files = collect(vol) entries = [] for p in files: raw = p.read_bytes() text = raw.decode("utf-8", errors="replace") entries.append({ "path": p.relative_to(REPO).as_posix(), "lang": lang_of(p), "bytes": len(raw), "lines": text.count("\n") + (0 if text.endswith("\n") else 1), "sha256": sha256(raw), "md5": md5(raw), "text": text, }) total = sum(e["bytes"] for e in entries) now = datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds") gi = git_info() out = ['<?xml version="1.0" encoding="UTF-8"?>', f'<audit-volume schema="swarm-dispatcher.audit-bundle.v2" volume={quoteattr(name)} ' f'generated={quoteattr(now)} generator="scripts/build_project_bundle.py">', f' <title>{escape(vol["title"])}</title>', f' <project>swarm-dispatcher</project>', f' <root>{escape(str(REPO))}</root>', f' <git is_git={quoteattr(gi["is_git"])}' + (f' head={quoteattr(gi.get("head",""))}/>' if gi["is_git"] == "true" else f'><note>{escape(gi.get("note",""))}</note></git>'), ' <manifest>', f' <files count="{len(entries)}" total_bytes="{total}"/>', ' <excluded>', ' <file path=".env*" reason="secrets"/>', ' <dir path="target/" reason="build artifacts"/>', ' <dir path=".venv/" reason="virtualenv"/>', ' <file path="*.docx|*.png" reason="binary"/>', ' </excluded>', ' <index>'] for e in entries: out.append(f' <entry path={quoteattr(e["path"])} lang={quoteattr(e["lang"])} ' f'bytes="{e["bytes"]}" lines="{e["lines"]}" ' f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}/>') out += [' </index>', ' </manifest>', ' <files>'] for e in entries: out.append(f' <file path={quoteattr(e["path"])} lang={quoteattr(e["lang"])} ' f'bytes="{e["bytes"]}" lines="{e["lines"]}" ' f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}>') if "]]>" in e["text"]: # XML-escaped body: strip trailing blanks per line for the same reason. body = "\n".join(line.rstrip() for line in e["text"].rstrip("\n").split("\n")) out += [' <content encoding="xml-escaped">', escape(body), ' </content>'] else: # Strip trailing blanks: the embedded files (e.g. REPORT_*.md with # markdown hard-breaks) would otherwise put trailing whitespace into # the bundle, which trips `git diff --check` on any regenerated # artifact. The bundle is an audit snapshot of content, not of # insignificant line padding. body = "\n".join(line.rstrip() for line in e["text"].rstrip("\n").split("\n")) out += [' <content><![CDATA[', body, ']]></content>'] out.append(' </file>') out += [' </files>', '</audit-volume>']
dest = OUT_DIR / f"PROJECT_{name}_BUNDLE_v0.4.xml" dest.write_text("\n".join(out) + "\n", encoding="utf-8") return dest, len(entries), total
def main() -> int: OUT_DIR.mkdir(parents=True, exist_ok=True) rows = [] for name, vol in VOLUMES.items(): dest, n, total = build_volume(name, vol) rows.append((name, dest, n, total, dest.stat().st_size, file_digest(dest, "sha256"), file_digest(dest, "md5"))) print(f"OK {name:6s} {dest.name} files={n} bytes={total} " f"xml={dest.stat().st_size}") print() for name, dest, n, total, xb, s, m in rows: print(f"{name}: files={n} src_bytes={total} xml_bytes={xb}") print(f" sha256={s}") print(f" md5={m}") return 0
if __name__ == "__main__": raise SystemExit(main())

#!/usr/bin/env bash # Одноразовый Postgres для ручных/интеграционных проверок — В ОТДЕЛЬНОМ контейнере. # # Зачем этот файл (инцидент 2026-10-13): роли Postgres глобальны для кластера, # а `step2/roles.sql` и `step2b/roles_2b.sql` делают `alter role ... password`. # Если поднять scratch-БД ВНУТРИ боевого кластера и применить к ней эти файлы с # тестовыми паролями (`-v w1_pw=c2_w1`), пароли боевых ролей молча меняются — # и весь прод-контур падает с `password authentication failed`. Именно так был # уронен прод. Правильный путь — scratch-контейнер: роли в нём изолированы. # # Использование: # scripts/scratch_pg.sh start [db] # поднять контейнер + применить схему/роли/миграции # scripts/scratch_pg.sh dsn [db] # напечатать DSN (host/port/user/password/dbname) # scripts/scratch_pg.sh psql [db] [-- args...] # psql внутрь scratch-контейнера # scripts/scratch_pg.sh stop [db] # удалить контейнер # # Пароли ролей внутри scratch-контейнера — фиксированные `c2_*`; они НЕ имеют # отношения к боевым (другой кластер). Боевой .env этот скрипт не читает. set -euo pipefail
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)" ACTION="${1:-start}" DB="${2:-scratch}" DB_NAME="${DB:-scratch}" DB_NAME="${DB_NAME//[^a-zA-Z0-9_]/_}" CONTAINER="swarm_scratch_pg_${DB_NAME}" # Фиксированные пароли ТОЛЬКО для изолированного scratch-кластера. ADMIN_PW="c2_admin" W1_PW="c2_w1"; W2_PW="c2_w2"; W_1_PW="c2_w_1"; GPU_1_PW="c2_gpu_1" WORKER_PW="c2_worker"; WATCHDOG_PW="c2_watchdog"; PLANNER_PW="c2_planner" REVIEWER_PW="c2_reviewer"; OPERATOR_PW="c2_operator"; CLI_PW="c2_cli"
die() { echo "ERROR: $*" >&2; exit 1; }
pg_exec() { docker exec -i -e PGPASSWORD="$ADMIN_PW" "$CONTAINER" psql -X -v ON_ERROR_STOP=1 -U postgres -d "$DB_NAME" "$@"; }
port() { docker port "$CONTAINER" 5432/tcp 2>/dev/null | awk -F: 'NR==1{print $NF}'; }
case "$ACTION" in start) command -v docker >/dev/null || die "docker не найден" if docker inspect "$CONTAINER" >/dev/null 2>&1; then die "контейнер $CONTAINER уже существует — сначала: scripts/scratch_pg.sh stop $DB" fi docker run -d --name "$CONTAINER" \ -e POSTGRES_DB="$DB_NAME" -e POSTGRES_USER=postgres -e "POSTGRES_PASSWORD=$ADMIN_PW" \ -p 127.0.0.1::5432 postgres:16-alpine >/dev/null local_ready=0 for _ in $(seq 1 60); do if docker exec -e PGPASSWORD="$ADMIN_PW" "$CONTAINER" psql -X -U postgres -d "$DB_NAME" -c 'select 1' >/dev/null 2>&1; then local_ready=1; break fi sleep 1 done ((local_ready == 1)) || die "postgres не поднялся в $CONTAINER" # Порядок ровно как в боевой цепочке (compose initdb.d). pg_exec < "$REPO_ROOT/schema/schema_v0.sql" >/dev/null pg_exec -v worker_pw="$WORKER_PW" -v watchdog_pw="$WATCHDOG_PW" -v planner_pw="$PLANNER_PW" \ -v reviewer_pw="$REVIEWER_PW" -v operator_pw="$OPERATOR_PW" -v cli_pw="$CLI_PW" \ < "$REPO_ROOT/step2/roles.sql" >/dev/null pg_exec -v w1_pw="$W1_PW" -v w2_pw="$W2_PW" -v w_1_pw="$W_1_PW" -v gpu_1_pw="$GPU_1_PW" \ < "$REPO_ROOT/step2b/roles_2b.sql" >/dev/null for p in roles_patch_planner_status.sql roles_patch_tool_call_audit.sql; do [ -f "$REPO_ROOT/step2/$p" ] && pg_exec < "$REPO_ROOT/step2/$p" >/dev/null done for mig in "$REPO_ROOT"/schema/migrations/*.sql; do [ -e "$mig" ] || continue pg_exec < "$mig" >/dev/null done echo "scratch postgres готов: container=$CONTAINER db=$DB_NAME port=$(port)" echo "DSN: $(PORT="$(port)" bash -c 'printf "host=127.0.0.1 port=%s user=postgres password=%s dbname=%s" "$PORT" "c2_admin" "'"$DB_NAME"'"')" ;; dsn) P="$(port)"; [ -n "$P" ] || die "контейнер $CONTAINER не запущен" printf 'host=127.0.0.1 port=%s user=postgres password=%s dbname=%s\n' "$P" "$ADMIN_PW" "$DB_NAME" ;; psql) shift 2 || true pg_exec "$@" ;; stop) docker rm -f "$CONTAINER" >/dev/null 2>&1 && echo "удалён $CONTAINER" || echo "не найден $CONTAINER" ;; *) die "неизвестное действие: $ACTION (start|dsn|psql|stop)" ;; esac

-- swarm roles v0.2: горизонтальное разделение прав.
-- Запуск (суперпользователем, ПОСЛЕ schema_v0.sql):
--   psql -v ON_ERROR_STOP=1 -d swarm \
--        -v worker_pw=... -v watchdog_pw=... -v planner_pw=... \
--        -v reviewer_pw=... -v operator_pw=... -v cli_pw=... -f roles.sql
-- Скрипт идемпотентен. Ничего из того, что делает schema_v0.sql, он не меняет по смыслу:
-- только владельца объектов, режим исполнения функций и права на них.
--
-- ⚠️  ВНИМАНИЕ: `alter role ... password` меняет пароль роли КЛАСТЕРОМ (роли
--     глобальны, не принадлежат БД). Запуск этого файла против ЛЮБОЙ БД
--     кластера меняет пароли сервисных ролей для ВСЕГО кластера, включая
--     боевой контур в том же кластере. Так был уронен прод (2026-10-13):
--     scratch-БД поднимали в прод-кластере и применяли roles.sql с тестовыми
--     паролями. Для тестов — отдельный контейнер (scripts/scratch_pg.sh),
--     НИКОГДА не scratch-БД внутри прод-кластера.

-- 1. Владелец объектов: не суперпользователь и без входа. SECURITY DEFINER-функции
--    исполняются от его имени, поэтому даже ошибка в функции не даёт прав суперпользователя.
select 'create role swarm_owner nologin'
 where not exists (select 1 from pg_roles where rolname = 'swarm_owner') \gexec

-- 2. Сервисные роли: только вход, никаких привилегий.
select format('create role %I login nosuperuser nocreatedb nocreaterole', r)
  from unnest(array['swarm_worker','swarm_watchdog','swarm_planner',
                    'swarm_reviewer','swarm_operator','swarm_cli']) r
 where not exists (select 1 from pg_roles where rolname = r) \gexec

-- Общая worker-роль содержит права-членство, но не является login identity.
alter role swarm_worker nologin;

alter role swarm_worker   password :'worker_pw';
alter role swarm_watchdog password :'watchdog_pw';
alter role swarm_planner  password :'planner_pw';
alter role swarm_reviewer password :'reviewer_pw';
alter role swarm_operator password :'operator_pw';
alter role swarm_cli      password :'cli_pw';

-- swarm_cli: учебная роль для человека-оператора с CLI (seed, review, reopen).
-- Это членство, а не отдельные права. К функциям воркера доступа у неё нет.
grant swarm_planner, swarm_reviewer, swarm_operator to swarm_cli;

-- 2b. Чтение для оператора: прямого доступа к таблицам нет ни у кого, поэтому статус отдаётся
--     функцией. Поля ограничены (нет contract, нет артефактов), чтобы не светить лишнее.
create or replace function task_status(p_limit int default 200)
returns table (id uuid, root_id uuid, state text, lease_epoch bigint, lease_owner text,
               attempts int, rework int, block_reason text, updated_at timestamptz)
language sql stable as $$
  select t.id, t.root_id, t.state, t.lease_epoch, t.lease_owner, t.attempts, t.rework,
         t.block_reason, t.updated_at
    from tasks t order by t.updated_at desc, t.id limit least(greatest(p_limit, 1), 1000)
$$;

-- 3. Передать владение таблицам (индексы и привязанные sequence переходят вместе с таблицей)
--    и всем функциям схемы.
do $$
declare r record;
begin
  for r in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
            where n.nspname = 'public' and c.relkind = 'r' loop
    execute format('alter table public.%I owner to swarm_owner', r.relname);
  end loop;
  for r in select p.oid::regprocedure as sig from pg_proc p
            join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public'
             and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e') loop
    execute format('alter function %s owner to swarm_owner', r.sig);
    -- 4. Исполнение от имени владельца + защита от подмены объектов через search_path
    --    (pg_temp последним: временная таблица с именем tasks ничего не перекроет).
    execute format('alter function %s security definer set search_path = public, pg_temp', r.sig);
  end loop;
end $$;

-- 5. Закрыть всё по умолчанию.
revoke all on schema public from public;
grant usage on schema public to swarm_owner, swarm_worker, swarm_watchdog,
      swarm_planner, swarm_reviewer, swarm_operator;
revoke all on all tables    in schema public from public;
revoke all on all sequences in schema public from public;
revoke all on all functions in schema public from public;

-- 6. Выдать нужное. Внутренние функции (append_event, assert_lease, lock_root,
--    validate_contract, event_hash, c_num) не выдаются никому: журнал нельзя подделать снаружи.
grant execute on function claim_task, heartbeat, save_artifact, complete_task, register_worker
  to swarm_worker;
-- F8: воркеру нужен свежий бюджет задачи (локальный + по дереву) перед вызовом LLM.
grant execute on function task_budget_state(uuid) to swarm_worker;
-- FIND-CODE-02: воркеру нужна диагностика последнего ревью при доработке.
grant execute on function task_rework_feedback(uuid, text, bigint) to swarm_worker;
grant execute on function reclaim_expired, promote_ready to swarm_watchdog;
grant execute on function add_task, add_dep, promote_ready to swarm_planner;
grant execute on function submit_review, verify_chain to swarm_reviewer;
grant execute on function reopen_task, verify_chain, task_status to swarm_operator;
-- F4: unblock_task получил новый параметр (p_new_budget_cap) — перевыдаём по
-- новой сигнатуре (старый грант висел на прежнем OID и после CREATE OR REPLACE
-- новой формы стал бы висеть на несуществующей функции).
grant execute on function unblock_task(uuid, text, bigint) to swarm_operator;

-- roles_patch_tool_call_audit.sql — v0.4 §7: аудит tool calls (shell tools). -- -- ПОЧЕМУ ПАТЧ, А НЕ ПРАВКА schema_v0.sql: -- schema_v0.sql неприкосновенен (ТЗ v0.4 §0 «Неприкосновенно»). -- -- ПОЧЕМУ ФУНКЦИЯ, А НЕ ПРЯМОЙ INSERT В events: -- step2/roles.sql §6 явно закрывает внутренние функции (append_event, assert_lease, -- lock_root, validate_contract, event_hash, c_num) — «журнал нельзя подделать снаружи». -- Прямой insert в events от имени swarm_worker нарушил бы это свойство. Поэтому -- воркер получает одну контролируемую точку входа: она проверяет, что аренда жива -- и принадлежит этому воркеру, и только затем пишет событие от имени swarm_owner. -- -- Применять ПОСЛЕ: schema_v0.sql → step2/roles.sql → step2b/roles_2b.sql. -- Идемпотентен.
-- 1. Разрешить kind='tool_call' (констрейнт расширяется, старые значения сохранены). alter table events drop constraint if exists events_kind_check; alter table events add constraint events_kind_check check (kind in ( 'created', 'dep_added', 'promoted', 'claimed', 'artifact_saved', 'completed', 'review_submitted', 'reclaimed', 'reopened', 'cascade_blocked', 'unblocked', 'tool_call'));
-- 2. Точка входа аудита: только для живого владельца аренды. create or replace function record_tool_call( p_task uuid, p_worker text, p_epoch bigint, p_event_id text, p_payload jsonb) returns boolean language plpgsql as $$ begin -- FIND-04: session_user обязан соответствовать p_worker (иначе WK003). -- Без этой строки воркер w1 мог записать событие от имени w2 на его аренде. perform assert_worker_identity(p_worker); -- Аренда жива и принадлежит этому воркеру? Иначе GR-ошибка. perform assert_lease(p_task, p_worker, p_epoch); return append_event(p_task, p_event_id, 'tool_call', p_worker, p_payload); end $$;
-- 3. Права: владелец-не-суперпользователь, исполнение от его имени, доступ только воркеру. alter function record_tool_call(uuid, text, bigint, text, jsonb) owner to swarm_owner; alter function record_tool_call(uuid, text, bigint, text, jsonb) security definer set search_path = public, pg_temp; revoke all on function record_tool_call(uuid, text, bigint, text, jsonb) from public; grant execute on function record_tool_call(uuid, text, bigint, text, jsonb) to swarm_worker;

-- swarm roles 2b v0.2: идентификация воркера.
-- Запуск ПОСЛЕ schema_v0.sql и roles.sql (суперпользователем):
--   psql -v ON_ERROR_STOP=1 -d swarm \
--     -v w1_pw=... -v w2_pw=... \
--     -f step2b/roles_2b.sql
--
-- ⚠️  ВНИМАНИЕ: `alter role ... password` (ниже) меняет пароль роли
--     КЛАСТЕРОМ — роли глобальны. Запуск против ЛЮБОЙ БД кластера меняет
--     пароли воркер-ролей для ВСЕГО кластера, включая боевой контур в том же
--     кластере. Так был уронен прод (2026-10-13). Для тестов — отдельный
--     контейнер (scripts/scratch_pg.sh), НИКОГДА не scratch-БД в прод-кластере.
--
-- Задача: закрыть самопровозглашённый worker_id.
-- Проверка активна только для ролей swarm_worker_*; другие роли не затронуты.
--
-- Код ошибки: WK003 worker_identity_mismatch.
--
-- ВАЖНО: schema_v0.sql не меняется. Проверка добавляется через
-- CREATE OR REPLACE. Следующая итерация схемы (v0.3) должна включить
-- её в тела функций.

-- ============================================================
-- 1. Нормализация и проверка идентичности
-- ============================================================

create or replace function normalize_worker_id(p_worker text)
returns text language sql immutable as $$
  select lower(regexp_replace(p_worker, '[-. ]', '_', 'g'))
$$;

create or replace function assert_worker_identity(p_worker text)
returns void language plpgsql as $$
declare v_expected text;
begin
  -- F3: идентификация закрыта по умолчанию (deny-by-default).
  -- Пропуск ТОЛЬКО при строгом совпадении session_user с ожидаемой
  -- per-worker ролью либо для суперпользователя. Раньше проверка была
  -- завёрнута в `if session_user like 'swarm_worker_%'`, поэтому под
  -- общей ролью swarm_worker (единственной, кому выданы обёртки) она
  -- молча ничего не проверяла — bypass. См. reference_fix_wave4.sql (F3).
  v_expected := 'swarm_worker_' || normalize_worker_id(p_worker);
  if session_user::text = v_expected then return; end if;
  if (select rolsuper from pg_roles where rolname = session_user) then return; end if;
  raise exception 'worker_identity_mismatch: session_user=% expected=%', session_user, v_expected
    using errcode = 'WK003';
end $$;

alter function normalize_worker_id(text) owner to swarm_owner;
alter function assert_worker_identity(text) owner to swarm_owner;
alter function normalize_worker_id(text) security definer set search_path = public, pg_temp;
alter function assert_worker_identity(text) security definer set search_path = public, pg_temp;

revoke all on function normalize_worker_id(text) from public;
revoke all on function assert_worker_identity(text) from public;
-- assert_worker_identity — не выдаём никому; вызывается только из обёрток.

-- ============================================================
-- 2. Переопределение пяти функций воркера с проверкой
-- ============================================================

-- 2.1. register_worker
create or replace function register_worker(p_id text, p_caps jsonb, p_tags text[] default '{}')
returns void language plpgsql as $$
begin
  perform assert_worker_identity(p_id);
  if (p_caps ? 'ram_gb' and jsonb_typeof(p_caps->'ram_gb') <> 'number')
     or (p_caps #> '{models,coder_class}' is not null
         and jsonb_typeof(p_caps #> '{models,coder_class}') <> 'number') then
    raise exception 'worker_invalid' using errcode = 'WK001';
  end if;
  insert into workers (id, capabilities, affinity_tags, last_seen)
  values (p_id, p_caps, coalesce(p_tags, '{}'), now())
  on conflict (id) do update
    set capabilities = excluded.capabilities, affinity_tags = excluded.affinity_tags,
        last_seen = now();
end $$;

-- 2.2. claim_task
create or replace function claim_task(p_worker text, p_lease_sec int default 300)
returns table (out_task_id uuid, out_contract jsonb, out_epoch bigint,
               out_budget bigint, out_spent bigint)
language plpgsql as $$
declare v_id uuid; v_epoch bigint;
begin
  if p_lease_sec <= 0 then
    raise exception 'lease duration must be positive' using errcode = 'CT001';
  end if;
  perform assert_worker_identity(p_worker);
  update workers set last_seen = now() where id = p_worker;
  if not found then raise exception 'worker_unknown' using errcode = 'WK002'; end if;

  select t.id into v_id
  from tasks t join workers w on w.id = p_worker
  where t.state = 'ready'
    -- F8: ДВОЙНОЙ бюджетный гейт (см. schema_v0.sql).
    and t.spent_tokens < t.budget_cap
    and (t.root_budget_cap is null
         or (select coalesce(sum(s.spent_tokens), 0) from tasks s where s.root_id = t.root_id)
            < t.root_budget_cap)
    and t.attempts < c_num(t.contract, '{budget,attempts}', 3)
    and c_num(w.capabilities, '{ram_gb}', 0) >= c_num(t.contract, '{needs,min_ram_gb}', 0)
    and c_num(w.capabilities, '{models,coder_class}', 0) >= c_num(t.contract, '{needs,coder_class}', 0)
    and not exists (select 1 from task_deps d join tasks p on p.id = d.dep_id
                    where d.task_id = t.id and p.state <> 'done')
  order by (select count(*) from jsonb_array_elements_text(
              coalesce(t.contract #> '{needs,affinity_tags}', '[]'::jsonb)) x
            where x = any (w.affinity_tags)) desc,
           t.priority desc, t.created_at, t.id
  for update of t skip locked
  limit 1;

  if v_id is null then return; end if;

  update tasks
     set state = 'leased', lease_owner = p_worker, lease_epoch = lease_epoch + 1,
         lease_until = now() + make_interval(secs => p_lease_sec), updated_at = now()
   where id = v_id returning lease_epoch into v_epoch;
  perform append_event(v_id, 'claim:' || v_id || ':' || v_epoch, 'claimed', p_worker,
                       jsonb_build_object('epoch', v_epoch));
  return query select t.id, t.contract, t.lease_epoch, t.budget_cap, t.spent_tokens
               from tasks t where t.id = v_id;
end $$;

-- 2.3. heartbeat
create or replace function heartbeat(p_task uuid, p_worker text, p_epoch bigint,
                                     p_extend_sec int default 300)
returns boolean language plpgsql as $$
begin
  if p_extend_sec <= 0 then
    raise exception 'lease extension must be positive' using errcode = 'CT001';
  end if;
  perform assert_worker_identity(p_worker);
  update tasks set lease_until = now() + make_interval(secs => p_extend_sec),
                   updated_at = now()
   where id = p_task and state = 'leased' and lease_owner = p_worker
     and lease_epoch = p_epoch and lease_until > now();
  if found then update workers set last_seen = now() where id = p_worker; end if;
  return found;
end $$;

-- 2.4. save_artifact
create or replace function save_artifact(p_task uuid, p_worker text, p_epoch bigint,
                                         p_ref text, p_storage text,
                                         p_content_type text default null,
                                         p_size bigint default null)
returns void language plpgsql as $$
begin
  perform assert_worker_identity(p_worker);
  perform assert_lease(p_task, p_worker, p_epoch);
  insert into artifacts (task_id, ref, created_by, lease_epoch, content_type, size_bytes, storage_path)
  values (p_task, p_ref, p_worker, p_epoch, p_content_type, p_size, p_storage)
  on conflict (task_id, ref) do update
     set created_by = excluded.created_by, lease_epoch = excluded.lease_epoch,
         content_type = excluded.content_type, size_bytes = excluded.size_bytes,
         storage_path = excluded.storage_path, created_at = now();
  perform append_event(p_task, 'art:' || p_epoch || ':' || p_ref, 'artifact_saved', p_worker,
                       jsonb_build_object('ref', p_ref));
end $$;

-- 2.5. complete_task
create or replace function complete_task(p_task uuid, p_worker text, p_epoch bigint,
                                         p_result_ref text, p_tokens bigint default 0)
returns text language plpgsql as $$
declare v_new text; v_spent bigint; v_cap bigint; v_root_cap bigint;
        v_root_spent bigint; v_ledger bigint;
begin
  perform assert_worker_identity(p_worker);
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_tokens < 0 then
    raise exception 'tokens must be non-negative' using errcode = 'CT001';
  end if;
  if not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  -- F8: единый источник истины — ledger `llm_calls` (триггер llm_calls_spend_sync).
  -- complete_task больше НЕ прибавляет p_tokens повторно (двойной учёт).
  -- FIND-CODE-04: фильтр по текущей эпохе (иначе запись за прошлую эпоху
  -- навсегда глушит учёт p_tokens новых эпох).
  select count(*) into v_ledger from llm_calls where task_id = p_task and lease_epoch = p_epoch;
  if v_ledger = 0 and p_tokens > 0 then
    update tasks set spent_tokens = spent_tokens + p_tokens where id = p_task;
  end if;
  select spent_tokens, budget_cap, root_budget_cap
    into v_spent, v_cap, v_root_cap from tasks where id = p_task;
  -- Issue #20: синхронизировано с schema/schema_v0.sql (Issue #3).
  v_new := case when v_spent > v_cap then 'budget_exhausted' else 'review' end;
  if v_new <> 'budget_exhausted' and v_root_cap is not null then
    select coalesce(sum(s.spent_tokens), 0) into v_root_spent
      from tasks s where s.root_id = (select root_id from tasks where id = p_task);
    if v_root_spent > v_root_cap then
      v_new := 'budget_exhausted';
    end if;
  end if;
  update tasks
     set state = v_new, result_ref = p_result_ref,
         lease_owner = null, lease_until = null, updated_at = now(),
         block_reason = case when v_new = 'budget_exhausted' then 'budget_exhausted' end
   where id = p_task;
  perform append_event(p_task, 'complete:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('ref', p_result_ref, 'new_state', v_new, 'tokens', p_tokens));
  return v_new;
end $$;

-- 2.6. FIND-NEW-01: fail_task — с identity-проверкой.
--      Раньше roles_2b перекрывал только 5 функций воркера, а fail_task/
--      fail_task_state остались без assert_worker_identity: тело шло под
--      SECURITY DEFINER, но не подтверждало, что p_worker = session_user.
--      Теперь все обёртки воркера проверяют identity единообразно.
create or replace function fail_task(p_task uuid, p_worker text, p_epoch bigint,
                                     p_result_ref text, p_reason text) returns text
language plpgsql as $$
begin
  perform assert_worker_identity(p_worker);
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_result_ref is not null
     and not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  update tasks
     set state = 'blocked', result_ref = coalesce(p_result_ref, result_ref),
         lease_owner = null, lease_until = null,
         block_reason = left('llm_error: ' || coalesce(p_reason, ''), 500), updated_at = now()
   where id = p_task;
  perform append_event(p_task, 'fail:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('failed', true, 'reason', left(coalesce(p_reason, ''), 500)));
  return 'blocked';
end $$;

-- 2.7. FIND-NEW-01: fail_task_state — с identity-проверкой.
create or replace function fail_task_state(p_task uuid, p_worker text, p_epoch bigint,
                                           p_result_ref text, p_reason text, p_state text)
returns text language plpgsql as $$
begin
  perform assert_worker_identity(p_worker);
  if p_state not in ('failed', 'budget_exhausted', 'blocked') then
    raise exception 'invalid target state %', p_state using errcode = 'CT001';
  end if;
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_result_ref is not null
     and not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  update tasks
     set state = p_state, result_ref = coalesce(p_result_ref, result_ref),
         lease_owner = null, lease_until = null,
         block_reason = left(coalesce(p_reason, ''), 500), updated_at = now()
   where id = p_task;
  perform append_event(p_task, 'fail:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('failed', true, 'state', p_state,
                                          'reason', left(coalesce(p_reason, ''), 500)));
  return p_state;
end $$;

-- Владелец и режим — для новых тел
alter function register_worker(text, jsonb, text[])          owner to swarm_owner;
alter function claim_task(text, int)                          owner to swarm_owner;
alter function heartbeat(uuid, text, bigint, int)             owner to swarm_owner;
alter function save_artifact(uuid, text, bigint, text, text, text, bigint) owner to swarm_owner;
-- FIND-NEW-01: fail_task / fail_task_state переопределены ниже с identity-проверкой.
alter function fail_task(uuid, text, bigint, text, text)          owner to swarm_owner;
alter function fail_task_state(uuid, text, bigint, text, text, text) owner to swarm_owner;
alter function complete_task(uuid, text, bigint, text, bigint) owner to swarm_owner;

alter function register_worker(text, jsonb, text[])          security definer set search_path = public, pg_temp;
alter function claim_task(text, int)                          security definer set search_path = public, pg_temp;
alter function heartbeat(uuid, text, bigint, int)             security definer set search_path = public, pg_temp;
alter function save_artifact(uuid, text, bigint, text, text, text, bigint) security definer set search_path = public, pg_temp;
alter function fail_task(uuid, text, bigint, text, text)          security definer set search_path = public, pg_temp;
alter function fail_task_state(uuid, text, bigint, text, text, text) security definer set search_path = public, pg_temp;
alter function complete_task(uuid, text, bigint, text, bigint) security definer set search_path = public, pg_temp;

-- ============================================================
-- 3. Роли для тестов
-- ============================================================
-- Соответствие worker_id → роль:
--   'w1'    → swarm_worker_w1      (без изменений)
--   'w2'    → swarm_worker_w2      (без изменений)
--   'w-1'   → swarm_worker_w_1     (нормализация: дефис → подчёркивание)
--   'GPU-1' → swarm_worker_gpu_1   (нормализация: регистр + дефис)
select 'create role swarm_worker_w1 login password ' || quote_literal(:'w1_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_w1') \gexec
select 'create role swarm_worker_w2 login password ' || quote_literal(:'w2_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_w2') \gexec
select 'create role swarm_worker_w_1 login password ' || quote_literal(:'w_1_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_w_1') \gexec
select 'create role swarm_worker_gpu_1 login password ' || quote_literal(:'gpu_1_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_gpu_1') \gexec

alter role swarm_worker_w1    password :'w1_pw';
alter role swarm_worker_w2    password :'w2_pw';
alter role swarm_worker_w_1   password :'w_1_pw';
alter role swarm_worker_gpu_1 password :'gpu_1_pw';

grant swarm_worker to swarm_worker_w1;
grant swarm_worker to swarm_worker_w2;
grant swarm_worker to swarm_worker_w_1;
grant swarm_worker to swarm_worker_gpu_1;

-- F4: fail_task — честный отказ воркera. Грант выдаётся ТОЛЬКО per-worker
-- login-ролям, НЕ общей swarm_worker: общая роль — не identity (см. F3),
-- и обёртки отказа должен вызывать только реальный воркер.
grant execute on function fail_task(uuid, text, bigint, text, text)
  to swarm_worker_w1, swarm_worker_w2, swarm_worker_w_1, swarm_worker_gpu_1;

-- Issue #3: fail_task_state вызывается из Rust (dispatcher.rs::fail_with_state)
-- на каждом пути отказа с явным целевым состоянием (failed / budget_exhausted /
-- blocked). Грант отсутствовал вовсе: под "revoke all on all functions from
-- public" воркер получал permission denied при ЛЮБОМ отказе с явным state,
-- т.е. весь F4-путь отказа был нерабочим в проде. Выдаём так же, как fail_task.
-- Смену состояния ограничивает сама функция (p_state in failed/budget_exhausted/
-- blocked) + assert_lease + assert_worker_identity.
grant execute on function fail_task_state(uuid, text, bigint, text, text, text)
  to swarm_worker_w1, swarm_worker_w2, swarm_worker_w_1, swarm_worker_gpu_1;

-- ============================================================
-- 3b. Defense-in-depth: каждой per-worker роли запрещён SET на
--     чужую роль (включая саму общую swarm_worker).
--
--     Без этого PG16 по умолчанию выдаёт set_option = true при
--     grant, и компрометация одной роли позволяет SET ROLE на
--     другую. Защита identity и так держится на session_user
--     (см. assert_worker_identity), но мы убираем и сам механизм.
--
--     Синтаксис проверен на PostgreSQL 16.15:
--       revoke set option for <role> from <role>
--     (не "REVOKE SET ON ROLE" — такого варианта в PG16 нет).
-- ============================================================
revoke set option for swarm_worker from swarm_worker_w1;
revoke set option for swarm_worker from swarm_worker_w2;
revoke set option for swarm_worker from swarm_worker_w_1;
revoke set option for swarm_worker from swarm_worker_gpu_1;

-- Перекрёстный запрет: ни одна worker-роль не имеет SET на любую
-- другую worker-роль (матрица N x N, включая саму себя).
revoke set option for swarm_worker_w1    from swarm_worker_w2, swarm_worker_w_1, swarm_worker_gpu_1;
revoke set option for swarm_worker_w2    from swarm_worker_w1, swarm_worker_w_1, swarm_worker_gpu_1;
revoke set option for swarm_worker_w_1   from swarm_worker_w1, swarm_worker_w2, swarm_worker_gpu_1;
revoke set option for swarm_worker_gpu_1 from swarm_worker_w1, swarm_worker_w2, swarm_worker_w_1;

#!/usr/bin/env python3 """Тест-арбитр волны 4 — F15: validate_contract должен требовать форму checks[].
Дефект: validate_contract проверял только непустоту checks (array), но НЕ форму элементов. Принимались ["pytest",42], [{"run":"cargo test"}], [{"type":""}], [{"type":123}] — задача без непустого строкового type затем вечно висит (её нельзя одобрить: RV003).
Фикс (эталон reference_fix_wave4.sql, блок F15): каждый элемент checks — объект с непустым строковым type; id (если задан) — непустая строка.
ТРИАДА: RED pre-fix : malformed checks принимаются (CT001 не летит) => падает GREEN fixed : CT001 на каждый malformed; валидные (с id и без) проходят RED after revert: снова принимаются => падает
Гейт BLOCKED (нет PG) — в tests/conftest.py. Запуск: W4_ADMIN_DSN="host=... user=postgres password=... dbname=c2_swarm" \ .venv/bin/python -m pytest -q tests/test_contract_form_f15.py """ import json import os
import psycopg2 import pytest
def _dsn() -> str: return os.environ.get("W4_ADMIN_DSN", "")
@pytest.fixture() def conn(): c = psycopg2.connect(_dsn()) c.autocommit = False yield c c.rollback() c.close()
def _contract(checks): return json.dumps( {"kind": "t", "checks": checks, "budget": {"attempts": 3, "max_rework": 3}} )
@pytest.mark.parametrize( "bad_checks", [ ["pytest", 42], # не объекты [{"run": "cargo test"}], # нет type [{"type": ""}], # пустой type [{"type": " "}], # пробельный type [{"type": 123}], # type не строка [{"type": "cmd", "id": ""}], # id задан, но пустой [{"type": "cmd", "id": 7}], # id не строка ], ) def test_f15_rejects_malformed_checks(conn, bad_checks): """validate_contract обязан отвергнуть каждый malformed элемент с CT001.""" cur = conn.cursor() with pytest.raises(psycopg2.DatabaseError) as e: cur.execute("select validate_contract(%s::jsonb)", (_contract(bad_checks),)) assert "contract_invalid" in str(e.value), ( f"F15: ожидался contract_invalid, получено: {e.value}" ) conn.rollback()
@pytest.mark.parametrize( "good_checks", [ [{"type": "cmd", "run": "cargo test"}], # без id (формат планировщика) [{"type": "cmd", "id": "unit", "run": "cargo test"}], # с id [{"type": "cmd"}, {"type": "lint", "id": "l1"}], # несколько, смешанно ], ) def test_f15_accepts_valid_checks(conn, good_checks): """Регрессия: валидные checks (в т.ч. без id, как у планировщика) проходят.""" cur = conn.cursor() cur.execute("select validate_contract(%s::jsonb)", (_contract(good_checks),)) conn.rollback()

"""Issue #2: сверка cost ledger с relay.fast — юнит- и DB-тесты.
Юнит-часть (без БД): разбор подтверждённого расхода и расчёт расхождения. DB-часть (при наличии PGDSN): снимок сверки пишется, view показывает алерт >5%. """ from __future__ import annotations
import importlib.util import os from decimal import Decimal from pathlib import Path
import pytest
REPO = Path(__file__).resolve().parent.parent
def _load_reconcile(): spec = importlib.util.spec_from_file_location( "reconcile_llm_cost", REPO / "scripts" / "reconcile_llm_cost.py" ) mod = importlib.util.module_from_spec(spec) spec.loader.exec_module(mod) return mod
rc = _load_reconcile()
# ---------- юнит: разбор подтверждённого расхода ----------
def test_parse_bare_number(): assert rc.parse_external("0.074") == Decimal("0.074")
def test_parse_usage_log_total_line(): """Строка usage-логов relay.fast: `Total: $0.005508`.""" text = "Time: 2026-10-12 18:19:26\nKey: 4 codex\nTotal: $0.005508\n" assert rc.parse_external(text) == Decimal("0.005508")
def test_parse_total_case_insensitive(): assert rc.parse_external("TOTAL $1.5") == Decimal("1.5")
def test_parse_rejects_garbage(): with pytest.raises(ValueError): rc.parse_external("no numbers here")
# ---------- юнит: расхождение ----------
def test_divergence_zero_when_equal(): assert rc.divergence_pct(Decimal("1"), Decimal("1")) == 0
def test_divergence_positive_when_local_higher(): # local 1.2, external 1.0 -> +20% assert rc.divergence_pct(Decimal("1.2"), Decimal("1.0")) == Decimal("20")
def test_divergence_negative_when_local_lower(): # local 0.8, external 1.0 -> -20% assert rc.divergence_pct(Decimal("0.8"), Decimal("1.0")) == Decimal("-20")
def test_divergence_external_zero_local_zero(): assert rc.divergence_pct(Decimal("0"), Decimal("0")) == 0
def test_divergence_external_zero_local_nonzero_is_full(): """Деления на ноль нет: при нулевом внешнем и ненулевом локальном — 100%.""" assert rc.divergence_pct(Decimal("0.5"), Decimal("0")) == Decimal("100")
def test_threshold_is_five_percent_by_default(): assert rc.DEFAULT_THRESHOLD_PCT == Decimal("5")
# ---------- DB: снимок сверки + view ----------
@pytest.fixture() def db(): dsn = os.environ.get("PGDSN") or os.environ.get("SWARM_DSN") if not dsn: pytest.skip("PGDSN/SWARM_DSN not set") psycopg2 = pytest.importorskip("psycopg2") conn = psycopg2.connect(dsn) yield conn conn.close()
def _reset(conn): with conn.cursor() as cur: cur.execute("delete from public.llm_cost_reconciliation") conn.commit()
def test_snapshot_stale_when_relay_unavailable(db): """relay.fast недоступен: снимок пишется как stale, без алерта, exit 0.""" _reset(db) local = rc.local_total(db) code = rc.record_snapshot(db, None, local, Decimal("5")) assert code == 0 with db.cursor() as cur: cur.execute("select stale, divergence_pct from public.llm_cost_reconciliation order by id desc limit 1") stale, pct = cur.fetchone() assert stale is True assert pct == 0
def test_first_confirmed_snapshot_is_baseline(db): """Первый подтверждённый снимок — базовая точка, без алерта (Issue #2).
Абсолютные суммы несопоставимы: `total_usage` relay.fast накопительный за всё время жизни ключа, а ledger считает с момента появления. """ _reset(db) local = rc.local_total(db) code = rc.record_snapshot(db, local + Decimal("1"), local, Decimal("5")) assert code == 0 with db.cursor() as cur: cur.execute("select is_baseline, alert from public.llm_cost_divergence") baseline, alert = cur.fetchone() assert baseline is True assert alert is False
def test_window_divergence_alert_above_threshold(db): """Приращение расходится >5% -> exit 1 и alert в view.""" _reset(db) local = rc.local_total(db) # Базовая точка. assert rc.record_snapshot(db, Decimal("10"), local, Decimal("5")) == 0 # Окно: внешне +1.0, локально +0.1 -> расхождение -90%. code = rc.record_snapshot(db, Decimal("11"), local + Decimal("0.1"), Decimal("5")) assert code == 1 with db.cursor() as cur: cur.execute("select alert, stale, is_baseline from public.llm_cost_divergence") alert, stale, baseline = cur.fetchone() assert alert is True assert stale is False assert baseline is False
def test_window_ok_within_threshold(db): """Приращения совпадают -> exit 0, alert = false.""" _reset(db) local = rc.local_total(db) assert rc.record_snapshot(db, Decimal("10"), local, Decimal("5")) == 0 code = rc.record_snapshot(db, Decimal("10.001"), local + Decimal("0.001"), Decimal("5")) assert code == 0 with db.cursor() as cur: cur.execute("select alert from public.llm_cost_divergence") (alert,) = cur.fetchone() assert alert is False
def test_negative_window_is_stale_not_alert(db): """Внешний расход уменьшился (сброс/смена ключа) -> stale, без алерта.""" _reset(db) local = rc.local_total(db) assert rc.record_snapshot(db, Decimal("10"), local, Decimal("5")) == 0 code = rc.record_snapshot(db, Decimal("5"), local + Decimal("1"), Decimal("5")) assert code == 0 with db.cursor() as cur: cur.execute("select stale, alert from public.llm_cost_divergence") stale, alert = cur.fetchone() assert stale is True assert alert is False
def test_view_deterministic_when_observed_at_ties(db): """Одинаковый `observed_at` (снимки в одной транзакции) — view берёт последнюю строку по `id`, а не произвольную.
Регрессия гейта #2c: `order by observed_at desc` без тайбрейкера давал недетерминированный результат, и `stale` терялся. `now()` в PostgreSQL — время начала транзакции, поэтому два снимка в одной транзакции имеют идентичный `observed_at`. """ _reset(db) local = rc.local_total(db) with db.cursor() as cur: # Оба снимка в ОДНОЙ транзакции -> одинаковый now(). cur.execute( "insert into public.llm_cost_reconciliation " "(external_total_usd, local_total_usd, divergence_pct, stale, is_baseline) " "values (10, 0, 0, false, true), (5, 1, 0, true, false) returning id, observed_at" ) rows = cur.fetchall() db.commit() assert rows[0][1] == rows[1][1], "тест требует одинаковый observed_at (tie)" with db.cursor() as cur: cur.execute("select stale, is_baseline, alert from public.llm_cost_divergence") stale, baseline, alert = cur.fetchone() # Последняя по id — stale-строка, она и должна быть выбрана. assert stale is True, "view обязан брать последнюю строку по id при tie observed_at" assert baseline is True # последний подтверждённый снимок остаётся базовой точкой assert alert is False
# ---------- юнит: разбор ответа relay.fast ----------
def test_parse_relay_usage_payload(): """Реальный ответ эндпоинта: {"object":"list","total_usage":0.2342}.""" import json as _json assert _json.loads('{"object":"list","total_usage":0.2342}')["total_usage"] == 0.2342
def test_fetch_relay_usage_returns_none_on_failure(): """Недоступный relay.fast -> None (stale), без исключения.""" assert rc.fetch_relay_usage("dummy", base_url="http://127.0.0.1:1", timeout=0.5) is None

"""Issue #7/#10: каталог моделей из прайса relay.fast — юнит-тесты (без сети).

Проверяем пересчёт прайса в USD за 1M токенов и отсев мусора, не трогая сеть:
`fetch_pricing` подменяется готовым словарём в формате `GET /api/pricing`.
"""
from __future__ import annotations

import importlib.util
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent


def _load():
    spec = importlib.util.spec_from_file_location(
        "fetch_model_catalog", REPO / "scripts" / "fetch_model_catalog.py"
    )
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


fmc = _load()


def _entry(name, model_ratio, group_ratio, completion_ratio,
           endpoints=("openai",), model_price=0):
    return {
        "model_name": name,
        "model_ratio": model_ratio,
        "group_ratio": {"default": group_ratio},
        "completion_ratio": completion_ratio,
        "model_price": model_price,
        "supported_endpoint_types": list(endpoints),
    }


def test_price_formula_matches_known_flash_model():
    """deepseek-v4-flash: 0.15 * 0.05 * 2 = 0.015 in, *4 = 0.060 out —
    та же цена, что в ledger (`llm_cost.rs`) и в `/api/log/token`."""
    p = {"data": [_entry("deepseek-v4-flash", 0.15, 0.05, 4)]}
    cat = fmc.to_catalog(p, [], [], only_chat=True)
    assert len(cat) == 1
    m = cat[0]
    assert abs(m["input_usd_per_1m"] - 0.015) < 1e-9
    assert abs(m["output_usd_per_1m"] - 0.060) < 1e-9


def test_chat_filter_excludes_image_models():
    p = {"data": [
        _entry("chat-model", 0.15, 0.05, 4),
        _entry("gpt-image-x", 0, 0.02, 0, endpoints=("image-generation",),
               model_price=0.5),
    ]}
    cat = fmc.to_catalog(p, [], [], only_chat=True)
    assert [m["name"] for m in cat] == ["chat-model"]


def test_priced_per_item_models_excluded():
    p = {"data": [_entry("per-image", 1, 0.02, 5, model_price=6)]}
    assert fmc.to_catalog(p, [], [], only_chat=True) == []


def test_nameless_entry_is_dropped():
    """В прайсе встречаются записи без имени (мусор разметки) — их не берём."""
    p = {"data": [_entry("", 1, 0.02, 5), _entry("real", 0.15, 0.05, 4)]}
    cat = fmc.to_catalog(p, [], [], only_chat=True)
    assert [m["name"] for m in cat] == ["real"]


def test_zero_or_missing_ratio_is_dropped():
    p = {"data": [
        _entry("zero", 0, 0.05, 4),
        {"model_name": "missing", "group_ratio": {"default": 0.05}},
    ]}
    assert fmc.to_catalog(p, [], [], only_chat=True) == []


def test_include_and_exclude_filters():
    p = {"data": [
        _entry("deepseek-v4-flash", 0.15, 0.05, 4),
        _entry("qwen3.8-flash", 0.075, 0.05, 3.13),
        _entry("gpt-6-sol", 1.0, 0.02, 5),
    ]}
    cat = fmc.to_catalog(p, ["flash"], [], only_chat=True)
    assert set(m["name"] for m in cat) == {"deepseek-v4-flash", "qwen3.8-flash"}
    cat2 = fmc.to_catalog(p, [], ["deepseek"], only_chat=True)
    assert "deepseek-v4-flash" not in [m["name"] for m in cat2]


def test_sorted_by_input_price():
    p = {"data": [
        _entry("expensive", 1.0, 0.02, 5),
        _entry("cheap", 0.05, 0.02, 5),
    ]}
    cat = fmc.to_catalog(p, [], [], only_chat=True)
    assert [m["name"] for m in cat] == ["cheap", "expensive"]


def test_quality_tier_heuristics():
    assert fmc.quality_tier_for("gpt-6-luna") == 2   # дешёвый суффикс важнее семейства
    assert fmc.quality_tier_for("gpt-6-sol") == 3
    assert fmc.quality_tier_for("deepseek-v4-flash") == 2
    assert fmc.quality_tier_for("deepseek-v4-pro") == 3
    assert fmc.quality_tier_for("claude-opus-5") == 3
    assert fmc.quality_tier_for("unknown-model") == 1

#!/usr/bin/env python3 """Тесты-арбитры волны 4 (F2, F15) — аудит swarm-dispatcher v0.4.
Назначение: КРАСНЫЕ на текущем стеке, ЗЕЛЁНЫЕ после правок F2/F15.
Запуск (против поднятого стека schema -> roles -> roles_2b, БЕЗ патча review): PGPASSWORD=... python3 -m pytest -q tests/test_review_gate_wave4.py
Требования: psycopg2, переменные окружения как в acceptance_harness.sh (PGDSN или ROLES_*). Файл использует суперпользовательский DSN (как test_v0.py).
Механика проверки: каждый тест СНАЧАЛА утверждает текущее (дефектное) поведение в маркере comment, но ассертит ЖЕЛАЕМОЕ. На коде до правки тест падает — это и есть красный лог. После правки F2/F15 — зелёный. Откат правки снова краснит. """ import os import uuid
import psycopg2 import pytest
def _dsn() -> str: return os.environ.get( "PGDSN", "dbname=c2_swarm user=postgres host=127.0.0.1 port=5432 password=pw", )
@pytest.fixture() def conn(): c = psycopg2.connect(_dsn()) c.autocommit = False yield c c.rollback() c.close()
def _mk_task_in_review(cur, checks, result_ref="r1"): """tasks в состоянии review с артефактом и result_ref (two-phase, FK-safe).""" t = str(uuid.uuid4()) cur.execute( """insert into tasks(id, root_id, state, contract, priority, attempts, budget_cap) values (%s,%s,'review',%s::jsonb,0,1,1000)""", (t, t, _contract(checks)), ) cur.execute( """insert into artifacts(task_id, ref, created_by, lease_epoch, storage_path) values (%s,%s,'author',0,'/tmp/'||%s)""", (t, result_ref, result_ref), ) cur.execute("update tasks set result_ref=%s where id=%s", (result_ref, t)) return t
def _contract(checks): import json
return json.dumps( {"kind": "t", "checks": checks, "budget": {"attempts": 3, "max_rework": 3}} )
def _submit(cur, t, checks_json, verdict="approved"): cur.execute( "select submit_review(%s,%s,'reviewer',%s,%s::jsonb)", (t, "r1", verdict, checks_json), )
# ---------------- F2: gate должен считать ПО КЛЮЧУ, а не по type ----------------
def test_f2_two_checks_same_type_need_two_passes(conn): """Два cmd-требования: один generic pass обязан быть отклонён (RV003).""" cur = conn.cursor() t = _mk_task_in_review( cur, [ {"type": "cmd", "run": "cargo test"}, {"type": "cmd", "run": "cargo clippy -- -D warnings"}, ], ) with pytest.raises(psycopg2.DatabaseError) as e: _submit(cur, t, '[{"type":"cmd","status":"pass"}]') assert "checks_failed" in str(e.value), "F2: один pass не должен закрывать два cmd" conn.rollback()
def test_f2_two_distinct_ids_need_two_passes(conn): """checks с id: для каждого id нужен свой pass.""" cur = conn.cursor() t = _mk_task_in_review( cur, [ {"type": "cmd", "id": "unit", "run": "cargo test"}, {"type": "cmd", "id": "lint", "run": "cargo clippy"}, ], ) with pytest.raises(psycopg2.DatabaseError) as e: _submit(cur, t, '[{"type":"cmd","id":"unit","status":"pass"}]') assert "checks_failed" in str(e.value), "F2: id 'lint' остался без pass" conn.rollback()
def test_f2_matching_passes_accepted(conn): """Позитивный: два pass с нужными ключами → done.""" cur = conn.cursor() t = _mk_task_in_review( cur, [ {"type": "cmd", "id": "unit", "run": "cargo test"}, {"type": "cmd", "id": "lint", "run": "cargo clippy"}, ], ) _submit( cur, t, '[{"type":"cmd","id":"unit","status":"pass"},{"type":"cmd","id":"lint","status":"pass"}]', ) cur.execute("select state from tasks where id=%s", (t,)) assert cur.fetchone()[0] == "done" conn.rollback()
# ---------------- F15: форма контракта ----------------
@pytest.mark.parametrize( "bad_checks", [ ["pytest", 42], [{"run": "cargo test"}], [{"type": ""}], [{"type": 123}], ], ) def test_f15_contract_rejects_malformed_checks(conn, bad_checks): """validate_contract не должен принимать checks без непустого строкового type.""" cur = conn.cursor() with pytest.raises(psycopg2.DatabaseError) as e: cur.execute("select validate_contract(%s::jsonb)", (_contract(bad_checks),)) assert "contract_invalid" in str(e.value) conn.rollback()
